// Erzeugt von scripts/build-data.mjs – nicht von Hand bearbeiten (Quelle: data/src).
window.MEDI_DETAILS = Object.assign(window.MEDI_DETAILS || {}, {"faktor-viii-inhibitor-bypassing-aktivitaet":{"wirkmechanismus":"Umgeht den durch Hemmkörper blockierten Teil der Gerinnung, sodass trotzdem Thrombin gebildet wird. Das Konzentrat aus Humanplasma enthält die Gerinnungsfaktoren II, IX und X vorwiegend in nicht aktivierter Form sowie Faktor VII hauptsächlich in aktivierter Form. Im Zentrum der Wirkung steht der Komplex aus Faktor Xa und Prothrombin, der unabhängig von Faktor VIII und IX Thrombin entstehen lässt.","nebenwirkungen":{"haeufig":["Überempfindlichkeitsreaktionen","Kopfschmerzen","Schwindel","Blutdruckabfall (Hypotonie)","Hautausschlag","Positiver Test auf Hepatitis-B-Antikörper (durch übertragene Antikörper, keine Infektion)"],"unbekannt":["Thromboembolische Ereignisse (Herzinfarkt, Schlaganfall, Lungenembolie, Venenthrombose)","Disseminierte intravasale Gerinnung (Verbrauchskoagulopathie)","Anaphylaktische Reaktion (schwere allergische Reaktion)","Anstieg des Hemmkörpertiters","Nesselsucht, Juckreiz","Atemnot, Brustschmerzen, Herzrasen","Übelkeit, Erbrechen, Durchfall","Fieber, Schüttelfrost"]},"schwangerschaft":"Nur bei klarer Notwendigkeit anwenden; in Schwangerschaft und Wochenbett ist das Thromboserisiko ohnehin erhöht. Erfahrungen fehlen.","stillzeit":"Nur bei klarer Notwendigkeit anwenden; Daten fehlen.","hinweise":["Höchstdosis beachten (in der Regel 100 E/kg als Einzeldosis und 200 E/kg pro Tag) – darüber steigt das Thromboserisiko.","Bei Brustschmerzen, Atemnot, Beinschwellung, Sprach- oder Sehstörungen sofort den Notfall aufsuchen.","Aus menschlichem Plasma hergestellt: Chargennummer dokumentieren; Impfungen gegen Hepatitis A und B werden empfohlen."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektions- oder Infusionslösung"]},"famciclovir":{"wirkmechanismus":"Hemmt die Vermehrung von Herpesviren in befallenen Zellen. Famciclovir ist ein Prodrug, das nach der Aufnahme im Darm und in der Leber (u. a. durch Aldehydoxidase) rasch in den Wirkstoff Penciclovir umgewandelt wird. In virusinfizierten Zellen wird Penciclovir durch die virale Thymidinkinase zu Penciclovirtriphosphat aktiviert, das die virale DNA-Polymerase hemmt und lange in der Zelle verbleibt. Latente Viren werden nicht beseitigt.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen"],"haeufig":["Schwindel","Übelkeit, Erbrechen, Bauchschmerzen, Durchfall","Abweichende Leberwerte","Hautausschlag, Juckreiz"],"gelegentlich":["Verwirrtheit und Schläfrigkeit (vor allem bei älteren Menschen)","Thrombozytopenie (Blutplättchenmangel)","Nesselsucht, Angioödem"],"selten":["Halluzinationen","Herzklopfen","Cholestatische Gelbsucht"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Krampfanfälle","Schwere Hautreaktionen (Erythema multiforme, Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Leukozytoklastische Vaskulitis (Gefässentzündung der Haut)"]},"schwangerschaft":"Nur begrenzte Erfahrungen; nur anwenden, wenn der Nutzen das mögliche Risiko überwiegt.","stillzeit":"Im Tierversuch geht Penciclovir in die Milch über; Anwendung nur, wenn der Nutzen das Risiko überwiegt.","hinweise":["Bei Gürtelrose möglichst innerhalb von 72 Stunden nach Auftreten des Ausschlags beginnen.","Kann unabhängig von den Mahlzeiten eingenommen werden.","Schwindel, Schläfrigkeit oder Verwirrtheit können die Fahrtüchtigkeit beeinträchtigen.","Genitalherpes bleibt ansteckend, auch unter Behandlung – Kondome verwenden, bei Beschwerden auf Geschlechtsverkehr verzichten."],"darreichung":["Filmtabletten"]},"famotidin":{"wirkmechanismus":"Vermindert die Bildung von Magensäure. Famotidin blockiert kompetitiv die Histamin-H2-Rezeptoren der säurebildenden Belegzellen der Magenschleimhaut und senkt so die basale sowie die durch Nahrung oder Histamin angeregte Säure- und Pepsinsekretion. Die Wirkung setzt nach etwa einer Stunde ein und hält 10–12 Stunden an. Anders als Cimetidin hemmt Famotidin die Cytochrom-P450-Enzyme praktisch nicht.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Schwindel","Obstipation (Verstopfung)","Durchfall"],"gelegentlich":["Mundtrockenheit","Übelkeit, Erbrechen","Bauchbeschwerden, Blähungen","Appetitlosigkeit","Müdigkeit","Hautausschlag, Juckreiz","Geschmacksstörungen"],"selten":["Überempfindlichkeitsreaktionen wie Anaphylaxie, Angioödem oder Bronchospasmus","Nesselsucht (Urtikaria)","Erhöhte Leberwerte, Gelbsucht durch Gallenstau","Gelenkschmerzen"],"sehrSelten":["Blutbildveränderungen bis zur Agranulozytose oder Panzytopenie","Vorübergehende psychische Störungen wie Verwirrtheit, Halluzinationen, Unruhe, Depression","Krampfanfälle (vor allem bei eingeschränkter Nierenfunktion)","Stevens-Johnson-Syndrom und toxische epidermale Nekrolyse (schwere Hautreaktionen)","QT-Verlängerung, AV-Block","Haarausfall","Impotenz, verminderte Libido"]},"schwangerschaft":"Nur anwenden, wenn eindeutig notwendig und nach ärztlicher Abwägung.","stillzeit":"Famotidin geht in die Muttermilch über – entweder abstillen oder auf die Behandlung verzichten.","hinweise":["Unabhängig von den Mahlzeiten einnehmen; abends eingenommen wirkt es besonders gegen nächtliche Säure.","Bei eingeschränkter Nierenfunktion die Dosis ärztlich anpassen lassen.","Rezeptfreie Tabletten gegen Sodbrennen ohne ärztlichen Rat nicht länger als 2 Wochen einnehmen."],"darreichung":["Filmtabletten"]},"fampridin":{"wirkmechanismus":"Erleichtert die Weiterleitung von Nervensignalen in Nervenfasern, deren schützende Myelinschicht durch die Multiple Sklerose geschädigt ist. Fampridin (4-Aminopyridin) blockiert spannungsabhängige Kaliumkanäle, die in entmarkten Nervenabschnitten freiliegen. Dadurch verringert sich der Kaliumausstrom während der Erregung, das Aktionspotenzial wird verlängert und kann die geschädigte Stelle eher überwinden. Fampridin wird grösstenteils unverändert über die Nieren ausgeschieden, zum Teil aktiv über den Transporter OCT2.","nebenwirkungen":{"sehrHaeufig":["Harnwegsinfekte"],"haeufig":["Schlaflosigkeit, Angst","Gleichgewichtsstörungen, Schwindel","Kribbeln (Parästhesien), Zittern","Kopfschmerzen","Schwäche (Asthenie)","Atemnot, Rachenschmerzen","Übelkeit, Erbrechen, Verstopfung, Verdauungsbeschwerden","Rückenschmerzen"],"gelegentlich":["Krampfanfälle","Anaphylaxie, Angioödem und andere Überempfindlichkeitsreaktionen","Verschlechterung einer Trigeminusneuralgie (Gesichtsschmerzen)","Herzrasen (Tachykardie)","Hautausschlag, Nesselsucht","Brustbeschwerden"]},"schwangerschaft":"Als Vorsichtsmassnahme während der Schwangerschaft nicht anwenden.","stillzeit":"Nicht empfohlen, da nicht bekannt ist, ob Fampridin in die Muttermilch übergeht.","hinweise":["Retardtabletten im Abstand von 12 Stunden ohne Essen einnehmen; ganz schlucken, nicht teilen oder zerkauen.","Sicherheitsrelevante Höchstdosis: 2 × 10 mg pro Tag. Eine vergessene Dosis nicht nachholen und nie doppelt einnehmen (Krampfgefahr).","Nach 2–4 Wochen wird geprüft, ob sich das Gehen verbessert hat; ohne Nutzen wird die Behandlung beendet."],"darreichung":["Retardtabletten"]},"faricimab":{"wirkmechanismus":"Hemmt gleichzeitig zwei Signalwege, die zu undichten, krankhaften Blutgefässen in der Netzhaut führen. Faricimab ist ein humanisierter bispezifischer IgG1-Antikörper, der sowohl VEGF-A als auch Angiopoietin-2 (Ang-2) bindet und neutralisiert. Die Ang-2-Hemmung stabilisiert zusätzlich die Gefässwände und vermindert Entzündung und Gefässdurchlässigkeit. Der Fc-Teil ist so verändert, dass der Antikörper rasch aus dem Blut entfernt wird.","nebenwirkungen":{"haeufig":["Grauer Star (Katarakt)","Bindehautblutung","Glaskörperabhebung, Glaskörpertrübungen (Mouches volantes)","Erhöhter Augeninnendruck","Augenschmerzen","Riss des retinalen Pigmentepithels (bei feuchter Makuladegeneration)"],"gelegentlich":["Endophthalmitis (schwere Infektion im Augeninneren)","Entzündung im Augeninneren (Uveitis, Iritis, Vitritis)","Netzhautriss oder Netzhautablösung","Augenreizung, Juckreiz, Fremdkörpergefühl, vermehrter Tränenfluss","Verschwommenes Sehen, Augenrötung","Hornhautabschürfung, Schmerzen bei der Injektion"],"unbekannt":["Retinale Vaskulitis (Entzündung der Netzhautgefässe), auch mit Gefässverschluss","Linsenverletzung durch die Injektion","Arterielle Thromboembolien (theoretisches Risiko von VEGF-Hemmern)"]},"schwangerschaft":"Nur anwenden, wenn der Nutzen das mögliche Risiko für das Ungeborene überwiegt, da die VEGF-Hemmung die Entwicklung beeinträchtigen kann. Frauen im gebärfähigen Alter verhüten während und mindestens 3 Monate nach der letzten Injektion.","stillzeit":"Stillen wird während der Behandlung nicht empfohlen.","hinweise":["Bei zunehmenden Augenschmerzen, Rötung, Lichtempfindlichkeit oder plötzlicher Sehverschlechterung nach der Injektion sofort die Augenärztin oder den Augenarzt aufsuchen.","Nach der Injektion kann das Sehen vorübergehend gestört sein – bis zur Erholung nicht Auto fahren.","Kontroll- und Injektionstermine einhalten; Behandlungslücken können das Sehvermögen gefährden."],"darreichung":["Injektionslösung zur Injektion in den Glaskörper"]},"febuxostat":{"wirkmechanismus":"Senkt die Harnsäure, indem es deren Bildung im Körper bremst. Febuxostat hemmt selektiv und stark die Xanthinoxidase, die Hypoxanthin und Xanthin zu Harnsäure umwandelt. Anders als Allopurinol ist es kein Purinabkömmling und wird vorwiegend in der Leber abgebaut, weshalb bei leichter bis mässiger Niereninsuffizienz keine Dosisanpassung nötig ist.","nebenwirkungen":{"haeufig":["Gichtanfälle zu Beginn der Behandlung","Kopfschmerzen","Durchfall, Übelkeit","Veränderte Leberwerte","Hautausschlag","Ödeme (Wassereinlagerungen)"],"gelegentlich":["Schwindel, Kribbeln, Schläfrigkeit, Geschmacksstörungen","Vorhofflimmern, Herzklopfen, Bluthochdruck","Erhöhtes TSH, Schilddrüsenunterfunktion","Bauchschmerzen, Sodbrennen, Verstopfung, Erbrechen","Gelenk- und Muskelschmerzen","Nierenversagen, Nierensteine, Blut im Urin","Juckreiz, Nesselsucht","Müdigkeit, Appetitveränderungen, Gewichtszunahme"],"selten":["Anaphylaxie und andere schwere Überempfindlichkeitsreaktionen, Angioödem","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS)","Hepatitis, Gelbsucht, Leberschäden","Blutbildstörungen (Agranulozytose, Thrombozytopenie, Panzytopenie)","Plötzlicher Herztod","Rhabdomyolyse (Muskelzerfall), interstitielle Nephritis"]},"schwangerschaft":"Nicht empfohlen; es liegen nur sehr wenige Erfahrungen vor.","stillzeit":"Nicht anwenden; es ist unbekannt, ob Febuxostat in die Muttermilch übergeht.","hinweise":["In den ersten Monaten treten häufig Gichtanfälle auf – nicht absetzen; während mindestens 6 Monaten wird vorbeugend Colchicin oder ein NSAR empfohlen.","Leberwerte vor Beginn und regelmässig während der Behandlung kontrollieren.","Bei Brustschmerzen, Atemnot, Lähmungen oder Sprachstörungen sofort notfallmässig ärztliche Hilfe holen.","Unabhängig von den Mahlzeiten einnehmen."],"darreichung":["Filmtabletten"]},"fedratinib":{"wirkmechanismus":"Verkleinert die Milz und lindert Beschwerden wie Müdigkeit, Nachtschweiss und Juckreiz bei Myelofibrose. Fedratinib hemmt bevorzugt die Januskinase JAK2 (sowohl die normale als auch die mutierte Form JAK2V617F) sowie FLT3. Dadurch wird die übermässige Signalübertragung über den JAK-STAT-Weg gebremst, die bei Myelofibrose zur unkontrollierten Blutzellbildung und Entzündung führt.","nebenwirkungen":{"sehrHaeufig":["Durchfall, Übelkeit, Erbrechen, Verstopfung","Anämie (Blutarmut), Thrombozytopenie (Mangel an Blutplättchen), Neutropenie","Harnwegsinfekte","Müdigkeit, Kopfschmerzen, Schwindel","Muskelkrämpfe","Erhöhte Leberwerte, erhöhte Lipase und Amylase","Erhöhte Nierenwerte (Kreatinin)"],"haeufig":["Wernicke-Enzephalopathie (Hirnschädigung durch Vitamin-B1-Mangel)","Bluthochdruck","Blutungen","Knochen- und Gliederschmerzen","Gewichtszunahme","Dysurie (Schmerzen beim Wasserlösen)"],"unbekannt":["Herzinsuffizienz","Thrombosen und Lungenembolie"]},"schwangerschaft":"Kontraindiziert. Frauen müssen während und bis mindestens 1 Monat nach der Behandlung zuverlässig verhüten.","stillzeit":"Während der Behandlung und bis 1 Monat nach der letzten Dosis nicht stillen.","hinweise":["Vor jeder Einnahme gegen Übelkeit vorbeugen wie verordnet; Einnahme mit einer fettreichen Mahlzeit kann Übelkeit und Erbrechen vermindern.","Verwirrtheit, Gangunsicherheit, Gedächtnis- oder Sehstörungen sofort ärztlich melden (Verdacht auf Wernicke-Enzephalopathie).","Regelmässige Kontrollen: Thiamin (Vitamin B1), Blutbild, Leber-, Nieren-, Amylase- und Lipasewerte."],"darreichung":["Hartkapseln"]},"felbamat":{"wirkmechanismus":"Dämpft die Erregbarkeit von Nervenzellen im Gehirn. Felbamat blockiert die Glycin-Bindungsstelle des NMDA-Glutamatrezeptors und verstärkt die Wirkung des hemmenden Botenstoffs GABA am GABA-A-Rezeptor; zudem hemmt es spannungsabhängige Natriumkanäle. Dadurch wird die Ausbreitung von Anfallsaktivität gebremst.","nebenwirkungen":{"haeufig":["Appetitlosigkeit, Gewichtsverlust","Schlaflosigkeit","Übelkeit, Erbrechen, Verdauungsbeschwerden","Kopfschmerzen, Schwindel","Schläfrigkeit, Müdigkeit","Doppelbilder, Gangunsicherheit"],"selten":["Aplastische Anämie (Versagen der Blutbildung)"],"sehrSelten":["Akutes Leberversagen"],"unbekannt":["Verminderung der weissen Blutkörperchen und Blutplättchen","Hautausschlag, Stevens-Johnson-Syndrom (schwere Hautreaktion)","Reizbarkeit und Verhaltensauffälligkeiten (v. a. bei Kindern)"]},"schwangerschaft":"Nicht anwenden, ausser bei zwingender Notwendigkeit nach sorgfältiger ärztlicher Abwägung.","stillzeit":"Felbamat geht in die Muttermilch über; nicht stillen.","hinweise":["Vor Beginn ausführliche Aufklärung über die Risiken; Blutbild und Leberwerte werden vor Beginn und häufig während der Behandlung kontrolliert.","Bei Fieber, Halsschmerzen, blauen Flecken, Blutungen, Blässe, Gelbfärbung von Haut oder Augen oder dunklem Urin sofort ärztliche Hilfe holen.","Nicht abrupt absetzen."],"darreichung":["Tabletten","Suspension zum Einnehmen"]},"felodipin":{"wirkmechanismus":"Senkt den Blutdruck, indem es die Blutgefässe erweitert. Felodipin hemmt den Einstrom von Calcium durch L-Typ-Calciumkanäle in die glatte Muskulatur der Arterien und wirkt dabei sehr gefässselektiv, kaum am Herzmuskel. Dadurch sinkt der Gefässwiderstand; bei Angina pectoris verbessert sich das Verhältnis von Sauerstoffangebot und -bedarf des Herzens. Als Retardtablette wirkt es über 24 Stunden.","nebenwirkungen":{"sehrHaeufig":["Periphere Ödeme (geschwollene Knöchel und Beine)"],"haeufig":["Kopfschmerzen","Flush (Hitzegefühl, Gesichtsrötung)"],"gelegentlich":["Herzklopfen, beschleunigter Puls","Schwindel, Kribbeln (Parästhesien)","Übelkeit, Bauchschmerzen","Hautausschlag, Juckreiz","Müdigkeit"],"selten":["Ohnmacht (Synkope)","Erbrechen","Nesselsucht","Gelenk- und Muskelschmerzen","Impotenz, sexuelle Funktionsstörungen"],"sehrSelten":["Zahnfleischwucherung (Gingivahyperplasie), Zahnfleischentzündung","Erhöhte Leberwerte","Lichtempfindlichkeit der Haut","Gefässentzündung der Haut (leukozytoklastische Vaskulitis)","Angioödem, Fieber","Häufiges Wasserlassen"]},"schwangerschaft":"Kontraindiziert; im Tierversuch traten Fehlbildungen auf.","stillzeit":"Geht in die Muttermilch über; Stillen wird während der Behandlung nicht empfohlen.","hinweise":["Retardtablette morgens unzerkaut und ungeteilt mit Wasser schlucken, nüchtern oder mit einer leichten Mahlzeit.","Keinen Grapefruitsaft trinken.","Auf gute Mundhygiene achten (Zahnfleischwucherung).","Knöchelschwellungen sind häufig und harmlos, sollten aber bei Zunahme ärztlich besprochen werden."],"darreichung":["Retardtabletten"]},"fenfluramin":{"wirkmechanismus":"Verstärkt im Gehirn die Wirkung des Botenstoffs Serotonin und senkt so die Anfallshäufigkeit. Fenfluramin und sein Abbauprodukt Norfenfluramin setzen Serotonin aus Nervenendigungen frei und regen bestimmte Serotonin-Rezeptoren (u. a. 5-HT1D, 5-HT2A, 5-HT2C) an; zusätzlich wirkt Fenfluramin am Sigma-1-Rezeptor. Die Wirkung von Norfenfluramin am 5-HT2B-Rezeptor gilt als Ursache der möglichen Herzklappen- und Lungengefässschäden.","nebenwirkungen":{"sehrHaeufig":["Verminderter Appetit, Gewichtsabnahme","Schläfrigkeit, Lethargie (Antriebslosigkeit), Müdigkeit","Durchfall","Fieber","Infekte der oberen Atemwege, Bronchitis, Ohrenentzündung","Auffälliger Herzultraschall (geringe Undichtigkeit der Herzklappen, meist ohne Krankheitswert)"],"haeufig":["Verhaltensauffälligkeiten, Aggressivität, Unruhe, Schlaflosigkeit, Stimmungsschwankungen","Gangunsicherheit (Ataxie), verminderte Muskelspannung, Zittern","Krampfanfälle, Status epilepticus","Verstopfung, vermehrter Speichelfluss, Erbrechen","Hautausschlag"],"unbekannt":["Serotoninsyndrom","Pulmonale arterielle Hypertonie (Lungenhochdruck)","Herzklappenerkrankung (bekannt aus der früheren Anwendung als Appetitzügler in höherer Dosis)"]},"schwangerschaft":"Vorsichtshalber nicht anwenden; nur nach sorgfältiger ärztlicher Abwägung.","stillzeit":"Nicht bekannt, ob Fenfluramin in die Muttermilch übergeht; Stillen nur nach ärztlicher Abwägung.","hinweise":["Herzultraschall vor Beginn, alle 6 Monate während und 3–6 Monate nach Ende der Behandlung.","Atemnot, Brustschmerzen, Herzklopfen, Ohnmacht oder Beinschwellungen sofort ärztlich abklären.","Gewicht regelmässig kontrollieren; die Dosis immer mit der beigelegten Dosierspritze abmessen.","Nicht abrupt absetzen."],"darreichung":["Lösung zum Einnehmen"]},"fenofibrat":{"wirkmechanismus":"Senkt vor allem die Triglyceride (Neutralfette) und erhöht das «gute» HDL-Cholesterin. Fenofibrat ist ein Prodrug, das im Körper rasch zur aktiven Fenofibrinsäure umgewandelt wird. Diese aktiviert den Kernrezeptor PPAR-alpha: Die Lipoproteinlipase wird aktiviert und die Bildung von Apolipoprotein C-III gehemmt, sodass triglyceridreiche Lipoproteine (VLDL) schneller abgebaut werden; gleichzeitig steigt die Bildung der HDL-Bausteine Apolipoprotein A-I und A-II. Auch LDL-Cholesterin und Harnsäure sinken mässig.","nebenwirkungen":{"haeufig":["Magen-Darm-Beschwerden: Bauchschmerzen, Übelkeit, Erbrechen, Durchfall, Blähungen","Erhöhte Leberwerte (Transaminasen)","Erhöhtes Homocystein im Blut"],"gelegentlich":["Thromboembolien (Lungenembolie, tiefe Venenthrombose)","Kopfschmerzen","Pankreatitis (Bauchspeicheldrüsenentzündung)","Gallensteine","Hautausschlag, Juckreiz, Nesselsucht","Muskelbeschwerden (Muskelschmerzen, Myositis, Muskelkrämpfe, Muskelschwäche)","Sexuelle Funktionsstörungen","Erhöhtes Kreatinin"],"selten":["Hepatitis (Leberentzündung)","Photosensibilität (Lichtempfindlichkeit der Haut)","Haarausfall","Abfall von Hämoglobin und weissen Blutkörperchen","Überempfindlichkeitsreaktionen","Erhöhter Harnstoff"],"unbekannt":["Rhabdomyolyse (Muskelzerfall)","Schwere Hautreaktionen (Erythema multiforme, Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Gelbsucht; Komplikationen von Gallensteinen (Gallenblasen- und Gallenwegsentzündung, Gallenkolik)","Interstitielle Lungenerkrankung","Müdigkeit"]},"schwangerschaft":"Nur nach strenger ärztlicher Nutzen-Risiko-Abwägung – Erfahrungen beim Menschen fehlen weitgehend.","stillzeit":"Nicht anwenden – der Übergang in die Muttermilch ist nicht ausreichend untersucht.","hinweise":["Je nach Präparat mit einer Mahlzeit einnehmen – Angabe in der Packungsbeilage beachten.","Leber- und Nierenwerte regelmässig kontrollieren; Muskelschmerzen oder -schwäche sofort melden.","Starke Sonnen- und UV-Bestrahlung meiden (Lichtempfindlichkeit).","Diät, Gewichtsreduktion und Verzicht auf Alkohol bleiben wichtig, besonders bei hohen Triglyceriden."],"darreichung":["Kapseln","Filmtabletten"]},"fentanyl":{"wirkmechanismus":"Lindert sehr starke Schmerzen, indem es an die körpereigenen Opioid-Andockstellen in Gehirn und Rückenmark bindet. Fentanyl ist ein synthetischer, stark fettlöslicher Agonist am μ-Opioidrezeptor und etwa 100-mal stärker wirksam als Morphin. Es hemmt Weiterleitung und Wahrnehmung von Schmerzreizen, dämpft aber auch das Atemzentrum. Der Abbau erfolgt in der Leber überwiegend über CYP3A4 zum unwirksamen Norfentanyl.","nebenwirkungen":{"sehrHaeufig":["Schläfrigkeit, Schwindel","Kopfschmerzen","Übelkeit, Erbrechen","Obstipation (Verstopfung)"],"haeufig":["Überempfindlichkeitsreaktionen","Schlaflosigkeit, Depression, Angst, Verwirrtheit, Halluzinationen","Zittern, Kribbeln","Herzklopfen, Herzrasen, Blutdruckanstieg","Atemnot","Appetitlosigkeit, Mundtrockenheit, Durchfall, Bauchschmerzen, Verdauungsbeschwerden","Starkes Schwitzen, Juckreiz, Hautausschlag","Harnverhalt, Wassereinlagerungen, Müdigkeit"],"gelegentlich":["Atemdepression (abgeschwächte Atmung)","Krampfanfälle, Bewusstseinsstörungen","Bradykardie (langsamer Puls), Blutdruckabfall","Ileus (Darmlähmung)","Erektionsstörung","Hautreaktionen an der Pflasterstelle","Entzugssymptome"],"selten":["Atemstillstand (Apnoe)","Miosis (enge Pupillen)"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Delir","Androgenmangel bei Langzeitanwendung","Serotonin-Syndrom","Abhängigkeit und Toleranz","Hyperalgesie (erhöhte Schmerzempfindlichkeit)"]},"schwangerschaft":"Nur wenn eindeutig erforderlich. Langdauernde Anwendung kann beim Neugeborenen ein Entzugssyndrom auslösen; während der Geburt nicht anwenden (Atemdepression beim Kind).","stillzeit":"Fentanyl geht in die Muttermilch über und kann beim Säugling Atemdepression verursachen. Während der Behandlung und mindestens 72 Stunden nach Entfernen des Pflasters nicht stillen.","hinweise":["Pflaster nicht zerschneiden und keiner Wärme aussetzen (Heizkissen, Sauna, heisses Bad); gebrauchte Pflaster mit der Klebeseite nach innen falten und für Kinder unerreichbar entsorgen.","Kein Alkohol; die Fahrtüchtigkeit ist vor allem zu Beginn und bei Dosisänderungen eingeschränkt.","Bei Atemproblemen oder ungewöhnlicher Schläfrigkeit sofort Hilfe holen; nach längerer Anwendung nicht abrupt absetzen.","Die verschiedenen Präparate gegen Durchbruchschmerzen sind nicht Mikrogramm für Mikrogramm austauschbar."],"darreichung":["Transdermale Pflaster","Buccaltabletten","Sublingualtabletten","Nasenspray","Injektionslösung"]},"fesoterodin":{"wirkmechanismus":"Entspannt den überaktiven Blasenmuskel, sodass die Blase mehr Urin speichern kann. Fesoterodin ist eine Vorstufe (Prodrug), die im Körper durch unspezifische Esterasen rasch in den eigentlichen Wirkstoff 5-Hydroxymethyltolterodin (5-HMT) umgewandelt wird – denselben aktiven Metaboliten wie bei Tolterodin. 5-HMT blockiert kompetitiv die Muskarinrezeptoren des Blasenmuskels und wird über CYP2D6 und CYP3A4 abgebaut.","nebenwirkungen":{"sehrHaeufig":["Mundtrockenheit"],"haeufig":["Schlaflosigkeit","Schwindel, Kopfschmerzen","Trockene Augen, trockener Hals","Bauchschmerzen, Durchfall, Verdauungsbeschwerden, Verstopfung, Übelkeit","Schmerzen beim Wasserlassen"],"gelegentlich":["Harnwegsinfektion","Geschmacksstörung, Schläfrigkeit","Verschwommenes Sehen","Drehschwindel","Herzrasen, Herzklopfen","Halsschmerzen, Husten, trockene Nase","Blähungen, Reflux","Anstieg der Leberwerte (ALT, GGT)","Hautausschlag, trockene Haut, Juckreiz","Harnverhalt, Restharn, verzögertes Wasserlassen","Müdigkeit"],"selten":["Angioödem","Verwirrtheit","Nesselsucht"]},"schwangerschaft":"Nicht empfohlen – es liegen keine ausreichenden Daten vor.","stillzeit":"Nicht anwenden – es ist nicht bekannt, ob der Wirkstoff in die Muttermilch übergeht.","hinweise":["Retardtabletten einmal täglich ganz mit Flüssigkeit schlucken, nicht teilen oder zerkauen.","Die volle Wirkung zeigt sich nach etwa 2–8 Wochen.","Verschwommenes Sehen, Schwindel und Schläfrigkeit können die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Retardtabletten"]},"fexofenadin":{"wirkmechanismus":"Blockiert die Wirkung von Histamin und lindert dadurch allergische Beschwerden wie Niesen, Juckreiz und Quaddeln. Fexofenadin ist der aktive Metabolit von Terfenadin, jedoch ohne dessen herzschädigende Wirkung, und ein selektiver Antagonist peripherer Histamin-H1-Rezeptoren. Es gelangt kaum ins Gehirn und macht daher praktisch nicht müde. Fexofenadin wird kaum verstoffwechselt; Aufnahme und Ausscheidung hängen von Transportproteinen wie P-Glykoprotein und OATP ab.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Schläfrigkeit","Schwindel","Übelkeit"],"gelegentlich":["Müdigkeit"],"unbekannt":["Überempfindlichkeitsreaktionen mit Angioödem, Engegefühl in der Brust, Atemnot, Hitzegefühl bis Anaphylaxie","Schlaflosigkeit, Nervosität, Albträume","Herzrasen (Tachykardie), Herzklopfen","Durchfall","Hautausschlag, Nesselsucht, Juckreiz","Verschwommenes Sehen"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur anwenden, wenn es ärztlich klar notwendig ist.","stillzeit":"Geht vermutlich in die Muttermilch über; Anwendung in der Stillzeit nicht empfohlen.","hinweise":["Mit Wasser vor einer Mahlzeit einnehmen, nicht mit Fruchtsaft.","Zu Antazida (Magensäurebindern) mindestens 2 Stunden Abstand halten.","Macht in der Regel nicht müde; die eigene Reaktion vor dem Autofahren trotzdem prüfen."],"darreichung":["Filmtabletten"]},"fezolinetant":{"wirkmechanismus":"Beruhigt das Temperaturzentrum im Gehirn, das in den Wechseljahren durch den Östrogenmangel überaktiv ist. Fezolinetant blockiert Neurokinin-3-Rezeptoren auf bestimmten Nervenzellen im Hypothalamus (KNDy-Neuronen), die ohne die bremsende Wirkung des Östrogens durch Neurokinin B übermässig angeregt werden. Dadurch normalisiert sich die Wärmeregulation, und Häufigkeit und Stärke der Hitzewallungen nehmen ab. Fezolinetant ist kein Hormon und ersetzt kein Östrogen.","nebenwirkungen":{"haeufig":["Durchfall","Bauchschmerzen","Schlaflosigkeit","Erhöhte Leberwerte (ALT, AST)"],"unbekannt":["Arzneimittelbedingte Leberschädigung (Leberentzündung, Gelbsucht)"]},"schwangerschaft":"Kontraindiziert; Fezolinetant ist nur für Frauen in den Wechseljahren bestimmt.","stillzeit":"Nicht vorgesehen; in der Stillzeit nicht anwenden.","hinweise":["Einmal täglich etwa zur gleichen Zeit mit Wasser einnehmen, mit oder ohne Essen.","Leberwerte vor Beginn und gemäss ärztlicher Anordnung in den ersten Monaten kontrollieren lassen.","Vor neuen Medikamenten (besonders Antibiotika und Antidepressiva) Ärztin, Arzt oder Apotheke fragen – einige erhöhen den Fezolinetant-Spiegel stark."],"darreichung":["Filmtabletten"]},"fibrinogen-human":{"wirkmechanismus":"Ersetzt fehlendes Fibrinogen, damit das Blut wieder stabile Gerinnsel bilden kann. Fibrinogen (Gerinnungsfaktor I) wird in der letzten Stufe der Gerinnung durch Thrombin in Fibrin umgewandelt, das sich zu einem Netz zusammenlagert; aktivierter Faktor XIII vernetzt und festigt dieses Fibrin. Das Konzentrat wird aus gepooltem menschlichem Plasma gewonnen, virusinaktiviert und hebt den Fibrinogenspiegel im Blut sofort an.","nebenwirkungen":{"unbekannt":["Allergische Reaktionen bis zum anaphylaktischen Schock (schwere allergische Reaktion)","Thromboembolische Ereignisse (Herzinfarkt, Lungenembolie, tiefe Venenthrombose)","Fieber","Hautausschlag, Nesselsucht","Übelkeit, Erbrechen"]},"schwangerschaft":"Nur bei klarer Notwendigkeit anwenden; kontrollierte Studien fehlen.","stillzeit":"Nur bei klarer Notwendigkeit anwenden; Daten fehlen.","hinweise":["Wird im Spital oder in spezialisierten Zentren langsam in die Vene gegeben; die Dosis richtet sich nach dem Fibrinogenspiegel.","Aus menschlichem Plasma hergestellt: Die Chargennummer wird dokumentiert; ein Restrisiko für die Übertragung von Krankheitserregern lässt sich nicht völlig ausschliessen.","Zeichen einer Thrombose (Beinschwellung, Brustschmerz, Atemnot) oder einer Allergie sofort melden."],"darreichung":["Pulver (und Lösungsmittel) zur Herstellung einer Injektions- oder Infusionslösung"]},"fibrinogen-thrombin":{"wirkmechanismus":"Ahmt die letzte Stufe der Blutgerinnung direkt an der Wunde nach. Beim Zusammentreffen der beiden Komponenten spaltet Thrombin das Fibrinogen zu Fibrin, das ein festes Netz bildet; Faktor XIII und Calcium vernetzen es zusätzlich. Das Gerinnsel haftet am Gewebe, stillt Sickerblutungen und dichtet ab; Aprotinin (in einigen Präparaten) bremst den vorzeitigen Abbau. Der Kleber wird im Körper wie ein natürliches Gerinnsel innerhalb von Tagen bis Wochen abgebaut.","nebenwirkungen":{"unbekannt":["Überempfindlichkeitsreaktionen bis zum anaphylaktischen Schock (schwere allergische Reaktion)","Lebensbedrohliche Gerinnsel oder Embolien bei versehentlicher Anwendung in ein Blutgefäss","Luft- oder Gasembolie bei Sprühanwendung mit Druckgas","Bildung von Antikörpern gegen Bestandteile des Klebers","Fieber, Wundschmerzen","Gestörte Einheilung eines Hauttransplantats (Artiss)"]},"schwangerschaft":"Sicherheit nicht belegt; nur bei klarer Notwendigkeit anwenden. Eine Parvovirus-B19-Infektion kann dem Ungeborenen schaden.","stillzeit":"Nur bei klarer Notwendigkeit anwenden; Daten fehlen.","hinweise":["Wird ausschliesslich von erfahrenen Chirurginnen und Chirurgen während Operationen auf Gewebe aufgetragen – nie in Blutgefässe.","Bei Sprühanwendung nur die vom Hersteller empfohlenen Geräte, Drücke und Abstände verwenden (Gefahr einer Gasembolie).","Aus menschlichem Plasma hergestellt: Die Chargennummer wird dokumentiert."],"darreichung":["Lösungen bzw. Pulver und Lösungsmittel für Gewebekleber (Zweikammerspritze, auch als Spray)","Versiegelungsmatrix (beschichteter Kollagenschwamm)"]},"fidaxomicin":{"wirkmechanismus":"Tötet das Darmbakterium Clostridioides difficile ab und schont dabei weitgehend die übrige Darmflora. Fidaxomicin hemmt die bakterielle RNA-Polymerase und wirkt dadurch bakterizid. Es hat ein schmales Wirkspektrum und hemmt zudem die Sporenbildung, weshalb Rückfälle seltener auftreten als unter Vancomycin. Der Wirkstoff wird kaum ins Blut aufgenommen und wirkt im Darm.","nebenwirkungen":{"haeufig":["Übelkeit","Erbrechen","Verstopfung"],"gelegentlich":["Verminderter Appetit","Schwindel","Kopfschmerzen","Geschmacksstörung","Aufgeblähter Bauch, Blähungen","Mundtrockenheit","Erhöhte Leberwerte","Hautausschlag, Juckreiz"],"unbekannt":["Überempfindlichkeitsreaktionen wie Angioödem und Atemnot"]},"schwangerschaft":"Keine ausreichenden Daten; aus Vorsicht in der Schwangerschaft möglichst nicht anwenden.","stillzeit":"Nicht bekannt, ob Fidaxomicin in die Muttermilch übergeht; da es kaum ins Blut gelangt, ist eine Anwendung nach ärztlicher Abwägung möglich.","hinweise":["Unabhängig von den Mahlzeiten einnehmen und die Behandlung (meist 10 Tage) nicht vorzeitig abbrechen.","Bei Schwellungen von Gesicht, Lippen oder Zunge oder bei Atemnot sofort ärztliche Hilfe holen.","Erneuten Durchfall nach Behandlungsende (möglicher Rückfall) ärztlich melden."],"darreichung":["Filmtabletten"]},"filgrastim":{"wirkmechanismus":"Regt das Knochenmark an, mehr infektabwehrende weisse Blutkörperchen (neutrophile Granulozyten) zu bilden und ins Blut abzugeben. Filgrastim ist ein gentechnisch hergestellter humaner G-CSF, der an den G-CSF-Rezeptor auf Vorläuferzellen der Granulozyten bindet. Dadurch werden Vermehrung, Ausreifung und Funktion der Neutrophilen gesteigert; die Zahl der Neutrophilen steigt innerhalb von 24 Stunden an. In höheren Dosen werden zudem Blutstammzellen aus dem Knochenmark ins Blut ausgeschwemmt.","nebenwirkungen":{"sehrHaeufig":["Knochen- und Muskelschmerzen","Kopfschmerzen","Übelkeit, Erbrechen, Durchfall","Thrombozytopenie (Mangel an Blutplättchen) und Anämie (Blutarmut)","Fieber, Müdigkeit","Haarausfall und Schleimhautentzündung (im Rahmen der Chemotherapie)"],"haeufig":["Milzvergrösserung","Erhöhte Werte von LDH und alkalischer Phosphatase im Blut","Blutdruckabfall oder Blutdruckanstieg","Husten, Atemnot, Bluthusten (Hämoptyse)","Hautausschlag, Hautrötung","Schmerzen beim Wasserlassen (Dysurie)"],"gelegentlich":["Überempfindlichkeitsreaktionen","ARDS (akutes Lungenversagen), Lungeninfiltrate, Lungenödem, Lungenblutung","Graft-versus-Host-Krankheit (nach Stammzelltransplantation)","Venenverschlusskrankheit der Leber","Eiweiss im Urin (Proteinurie)","Erhöhte Harnsäure","Osteoporose"],"selten":["Milzriss (Milzruptur)","Sichelzellkrisen bei Sichelzellkrankheit","Kapillarlecksyndrom","Aortitis (Entzündung der Hauptschlagader)","Sweet-Syndrom (akute fieberhafte Hauterkrankung)","Hautvaskulitis (Gefässentzündung)","Glomerulonephritis (Nierenentzündung)","Pseudogicht"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Myelodysplastisches Syndrom oder akute myeloische Leukämie (bei bestimmten Patientengruppen)"]},"schwangerschaft":"Erfahrungen sind begrenzt; nur nach strenger ärztlicher Nutzen-Risiko-Abwägung anwenden.","stillzeit":"Ob Filgrastim in die Muttermilch übergeht, ist nicht bekannt; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Bei Schmerzen im linken Oberbauch oder in der linken Schulterspitze sofort ärztliche Hilfe holen (möglicher Milzriss).","Knochenschmerzen sind häufig und lassen sich meist mit einfachen Schmerzmitteln wie Paracetamol lindern.","Während der Behandlung wird das Blutbild regelmässig kontrolliert.","Fertigspritzen im Kühlschrank lagern, nicht einfrieren."],"darreichung":["Injektions- oder Infusionslösung (Fertigspritze, Durchstechflasche)"]},"finasterid":{"wirkmechanismus":"Verkleinert die Prostata bzw. bremst den Haarausfall, indem es die Bildung des stark wirksamen männlichen Hormons Dihydrotestosteron (DHT) vermindert. Finasterid hemmt spezifisch das Enzym 5-Alpha-Reduktase Typ 2, das in Prostata, Haarwurzeln und Haut Testosteron in DHT umwandelt. Der DHT-Spiegel im Blut sinkt um rund 70 %, in der Prostata noch stärker, während der Testosteronspiegel weitgehend unverändert bleibt. Die Prostata schrumpft langsam über Monate; beim Haarausfall ist eine Wirkung frühestens nach 3–6 Monaten zu erwarten.","nebenwirkungen":{"haeufig":["Erektionsstörung (Impotenz) – bei 1 mg gelegentlich","Verminderte Libido (Lust auf Sex) – bei 1 mg gelegentlich","Vermindertes Ejakulatvolumen"],"gelegentlich":["Ejakulationsstörungen","Spannungsgefühl oder Vergrösserung der Brust (Gynäkomastie)","Hautausschlag"],"unbekannt":["Depression, Angst, Suizidgedanken","Sexuelle Funktionsstörungen, die nach dem Absetzen anhalten","Hodenschmerzen, Blut im Sperma","Männliche Unfruchtbarkeit, verminderte Spermienqualität","Überempfindlichkeitsreaktionen mit Juckreiz, Nesselsucht, Angioödem","Herzklopfen","Erhöhte Leberwerte","Brustkrebs beim Mann"]},"schwangerschaft":"Kontraindiziert. Schwangere und Frauen, die schwanger werden könnten, dürfen zerbrochene oder zerdrückte Tabletten nicht berühren: der Wirkstoff kann über die Haut aufgenommen werden und bei einem männlichen Fötus Fehlbildungen der Geschlechtsorgane verursachen.","stillzeit":"Nicht für Frauen bestimmt.","hinweise":["Ganze, unbeschädigte Filmtabletten sind beim Berühren unbedenklich; zerbrochene Tabletten von Schwangeren fernhalten.","Die Wirkung tritt erst nach Monaten ein: gegen Haarausfall mindestens 3–6 Monate regelmässig einnehmen; nach dem Absetzen geht der Effekt innerhalb etwa eines Jahres wieder verloren.","Bei einer PSA-Bestimmung die Einnahme angeben, da der Wert halbiert wird.","Stimmungsveränderungen oder anhaltende sexuelle Probleme ärztlich besprechen."],"darreichung":["Filmtabletten"]},"finerenon":{"wirkmechanismus":"Schützt Nieren und Herz, indem es die überaktiven Signale des Hormons Aldosteron blockiert. Finerenon ist ein nichtsteroidaler, hochselektiver Antagonist des Mineralokortikoid-Rezeptors, dessen Überaktivierung Entzündung und Fibrose (Vernarbung) in Niere, Herz und Gefässen fördert. Es vermindert so die Eiweissausscheidung im Urin und verlangsamt den Verlust der Nierenfunktion. Den Blutdruck senkt es nur wenig, und an Androgen- oder Progesteronrezeptoren bindet es praktisch nicht. Finerenon wird überwiegend über CYP3A4 abgebaut.","nebenwirkungen":{"sehrHaeufig":["Hyperkaliämie (erhöhtes Kalium)"],"haeufig":["Hyponatriämie (Natriummangel)","Hypotonie (niedriger Blutdruck)","Juckreiz","Abnahme der glomerulären Filtrationsrate (Nierenfunktion), meist zu Beginn und rückbildungsfähig"],"gelegentlich":["Abnahme des Hämoglobins (Blutfarbstoff)"]},"schwangerschaft":"Nicht anwenden, ausser bei zwingender Notwendigkeit (im Tierversuch fruchtschädigend); Frauen im gebärfähigen Alter müssen während der Behandlung zuverlässig verhüten.","stillzeit":"Ein Risiko für den Säugling kann nicht ausgeschlossen werden; während der Behandlung nicht stillen.","hinweise":["Kalium und Nierenfunktion vor Beginn, nach 4 Wochen und danach regelmässig kontrollieren lassen.","Grapefruit und Grapefruitsaft meiden; keine Kaliumpräparate oder kaliumhaltigen Salzersatzmittel ohne Rücksprache.","Vor jedem neuen Medikament, besonders Antibiotika, Pilzmitteln und Johanniskraut, auf Finerenon hinweisen.","Tablette kann bei Schluckbeschwerden zerdrückt und mit Wasser oder weicher Nahrung (z. B. Apfelmus) eingenommen werden."],"darreichung":["Filmtabletten"]},"fingolimod":{"wirkmechanismus":"Hält bestimmte weisse Blutkörperchen in den Lymphknoten zurück, damit sie nicht ins Gehirn und Rückenmark gelangen und dort Entzündungen auslösen. Fingolimod ist ein Prodrug; der Wirkmetabolit Fingolimod-Phosphat bindet an Sphingosin-1-Phosphat-Rezeptoren (S1P1, 3, 4 und 5) und führt zur Internalisierung von S1P1 auf Lymphozyten. Diese können die Lymphknoten nicht mehr verlassen, ihre Zahl im Blut sinkt auf etwa 20–30 % des Ausgangswerts. Über S1P-Rezeptoren am Herzen verlangsamt es zu Beginn vorübergehend den Herzschlag.","nebenwirkungen":{"sehrHaeufig":["Grippe (Influenza)","Sinusitis (Nasennebenhöhlenentzündung)","Kopfschmerzen","Durchfall","Rückenschmerzen","Husten","Erhöhte Leberwerte (ALT)"],"haeufig":["Herpesvirus-Infektionen, Bronchitis","Basalzellkarzinom (heller Hautkrebs)","Lymphopenie und Leukopenie (Mangel an weissen Blutkörperchen)","Pulsverlangsamung (Bradykardie) und AV-Block bei Behandlungsbeginn","Bluthochdruck","Depression, Schwindel, Migräne","Verschwommenes Sehen","Atemnot, Haarausfall"],"gelegentlich":["Lungenentzündung","Malignes Melanom (schwarzer Hautkrebs)","Makulaödem (Schwellung der Netzhautmitte)","Krampfanfälle","Thrombozytopenie (Mangel an Blutplättchen)"],"selten":["Lymphome","PRES (posteriores reversibles Enzephalopathie-Syndrom)"],"sehrSelten":["Kaposi-Sarkom"],"unbekannt":["PML (progressive multifokale Leukenzephalopathie)","Kryptokokken-Infektionen (inkl. Hirnhautentzündung)","Schwere Leberschädigung bis Leberversagen","Überempfindlichkeitsreaktionen","Schwere Verschlechterung der MS nach dem Absetzen"]},"schwangerschaft":"Kontraindiziert (fruchtschädigend). Frauen im gebärfähigen Alter müssen während und bis 2 Monate nach dem Absetzen zuverlässig verhüten; vor Beginn Schwangerschaftstest.","stillzeit":"Nicht stillen während der Behandlung.","hinweise":["Erste Einnahme unter ärztlicher Überwachung (mindestens 6 Stunden, EKG); nach einem Therapieunterbruch kann eine erneute Überwachung nötig sein.","Augenuntersuchung 3–4 Monate nach Beginn; Blutbild, Leberwerte und Haut regelmässig kontrollieren.","Nicht eigenmächtig absetzen – die MS kann sich danach stark verschlechtern.","Bei Fieber, starken Kopfschmerzen, Sehstörungen oder neuen neurologischen Beschwerden ärztlich abklären lassen."],"darreichung":["Hartkapseln"]},"flecainid":{"wirkmechanismus":"Bremst die elektrische Erregungsleitung im Herzen und verhindert dadurch kreisende Erregungen, die Herzrasen auslösen. Flecainid blockiert die schnellen Natriumkanäle der Herzmuskelzellen stark und löst sich nur langsam wieder von ihnen (Klasse IC). Dadurch werden die Leitungsgeschwindigkeit in Vorhöfen, AV-Knoten, His-Purkinje-System, Kammern und zusätzlichen Leitungsbahnen deutlich verlangsamt (im EKG Verbreiterung von PR- und QRS-Intervall). Flecainid wird teilweise über CYP2D6 abgebaut und zu einem grossen Teil über die Niere ausgeschieden.","nebenwirkungen":{"sehrHaeufig":["Schwindel, Benommenheit","Sehstörungen (Doppelbilder, verschwommenes Sehen, Schwierigkeiten beim Scharfstellen)"],"haeufig":["Neu ausgelöste oder verstärkte Herzrhythmusstörungen (Proarrhythmie), besonders bei struktureller Herzerkrankung","Atemnot","Schwäche, Müdigkeit","Fieber","Ödeme (Wassereinlagerungen)"],"gelegentlich":["Übelkeit, Erbrechen, Verstopfung, Bauchschmerzen, Durchfall, Blähungen","Appetitlosigkeit","Verminderung von roten und weissen Blutkörperchen sowie Blutplättchen","Allergische Hautreaktionen, Haarausfall"],"selten":["Halluzinationen, Depression, Verwirrtheit, Angst, Schlaflosigkeit","Kribbeln, Gangunsicherheit, Zittern, Ohnmacht (Synkope), Krampfanfälle","Periphere Neuropathie (Nervenschädigung)","Ohrensausen (Tinnitus), Drehschwindel","Pneumonitis (Lungenentzündung ohne Erreger)","Erhöhte Leberwerte, Gelbsucht","Nesselsucht"],"sehrSelten":["Hornhautablagerungen","Lichtempfindlichkeit der Haut"],"unbekannt":["AV-Block 2. und 3. Grades, Sinusarrest, Bradykardie, Kammerflimmern, Herzstillstand","Verschlechterung einer Herzinsuffizienz, Blutdruckabfall","Demaskierung eines Brugada-Syndroms","Lungenfibrose und interstitielle Lungenerkrankung"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung: Flecainid gelangt zum Ungeborenen, und in Tierversuchen traten Fehlbildungen auf.","stillzeit":"Geht in die Muttermilch über; Anwendung in der Stillzeit nur nach ärztlicher Abwägung.","hinweise":["Die Behandlung wird unter EKG-Kontrolle begonnen; regelmässige EKG- und bei eingeschränkter Nierenfunktion Spiegelkontrollen.","Bei neuem Herzrasen, Ohnmacht, Atemnot oder Wassereinlagerungen sofort ärztliche Hilfe holen.","Jedes neue Medikament ärztlich auf Wechselwirkungen prüfen lassen, besonders Antidepressiva und Antibiotika.","Durchfall oder Erbrechen können den Kaliumspiegel senken und das Risiko von Rhythmusstörungen erhöhen."],"darreichung":["Tabletten"]},"flohsamenschalen-ispaghula":{"wirkmechanismus":"Quillt im Darm auf und vergrössert dadurch die Stuhlmenge, die den Darm auf natürliche Weise zur Entleerung anregt. Die Schalen der Samen von Plantago ovata enthalten Schleimstoffe (Arabinoxylane), die ein Vielfaches ihres Gewichts an Wasser binden und ein Gel bilden. Dieses macht harten Stuhl weicher und gleitfähiger, dehnt die Darmwand und regt so die Peristaltik an. Bei dünnem Stuhl kann das Gel überschüssiges Wasser binden. Die Wirkung tritt nach 12–72 Stunden ein; die Schleimstoffe werden nicht ins Blut aufgenommen.","nebenwirkungen":{"unbekannt":["Blähungen und Völlegefühl, vor allem zu Beginn","Bauchschmerzen","Darm- oder Speiseröhrenverschluss sowie Kotstau bei zu wenig Flüssigkeit","Überempfindlichkeitsreaktionen wie Schnupfen, Bindehautentzündung, Asthma, Hautausschlag, Juckreiz","Anaphylaxie (schwere allergische Reaktion)"]},"schwangerschaft":"Kann angewendet werden; die Schleimstoffe werden nicht ins Blut aufgenommen. Gilt bei Verstopfung in der Schwangerschaft als Mittel der ersten Wahl.","stillzeit":"Kann angewendet werden.","hinweise":["Jede Dosis in einem grossen Glas Wasser (mindestens 150 ml) einrühren, sofort trinken und reichlich nachtrinken – zu wenig Flüssigkeit kann Speiseröhre oder Darm verstopfen.","Nicht unmittelbar vor dem Schlafengehen und nicht im Liegen einnehmen.","Andere Medikamente mit zeitlichem Abstand einnehmen (mindestens 30–60 Minuten).","Die volle Wirkung kann 1–3 Tage dauern; Blähungen bessern sich meist nach einigen Tagen."],"darreichung":["Pulver","Granulat"]},"flucloxacillin":{"wirkmechanismus":"Tötet Bakterien ab, indem es den Aufbau ihrer Zellwand verhindert. Flucloxacillin hemmt die Penicillin-bindenden Proteine und damit die Quervernetzung des Peptidoglykans (bakterizide Wirkung). Dank seiner Seitenkette ist es gegen die Penicillinase (Beta-Laktamase) der Staphylokokken stabil und deshalb ein Mittel der Wahl bei Infektionen mit Methicillin-empfindlichem Staphylococcus aureus. Gegen MRSA, Enterokokken und die meisten gramnegativen Bakterien wirkt es nicht.","nebenwirkungen":{"haeufig":["Leichte Magen-Darm-Beschwerden (Übelkeit, Durchfall, Bauchschmerzen)"],"gelegentlich":["Hautausschlag, Nesselsucht, Purpura (punktförmige Hautblutungen)"],"sehrSelten":["Leberentzündung und Gelbsucht durch Gallestau (auch verzögert bis 2 Monate nach Behandlungsende, teils langwierig)","Neutropenie bis Agranulozytose, Thrombozytopenie","Anaphylaxie und Angioödem","Pseudomembranöse Kolitis (schwere Darmentzündung)","Schwere Hautreaktionen (Erythema multiforme, Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Gelenk- und Muskelschmerzen, Fieber","Interstitielle Nephritis (Nierenentzündung)"],"unbekannt":["Metabolische Azidose mit erhöhter Anionenlücke (vor allem zusammen mit Paracetamol)","Eosinophilie","Akute generalisierte exanthematische Pustulose (AGEP)","Venenreizung an der Infusionsstelle"]},"schwangerschaft":"Nach ärztlicher Abwägung möglich; bisher keine Hinweise auf eine Schädigung des Kindes.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Anwendung nach Abwägung möglich (beim Säugling Durchfall oder Sensibilisierung möglich).","hinweise":["Kapseln nüchtern mit einem Glas Wasser einnehmen: mindestens 1 Stunde vor oder 2 Stunden nach dem Essen.","Gelbe Haut oder Augen, dunkler Urin oder heller Stuhl – auch Wochen nach Behandlungsende – sofort ärztlich abklären lassen.","Paracetamol nur nach ärztlicher Rücksprache gleichzeitig einnehmen.","Bei einer Behandlung über mehr als 14 Tage werden die Leberwerte kontrolliert."],"darreichung":["Kapseln","Pulver zur Herstellung einer Injektions- oder Infusionslösung"]},"fluconazol":{"wirkmechanismus":"Hemmt die Bildung eines wichtigen Bausteins der Pilzzellwand und stoppt so das Pilzwachstum. Fluconazol blockiert das pilzeigene Cytochrom-P450-Enzym Lanosterol-14α-Demethylase, wodurch kein Ergosterol mehr für die Zellmembran gebildet wird und sich toxische Sterolvorstufen anreichern. Es wird gut aufgenommen, verteilt sich auch in Liquor und Urin und wird überwiegend unverändert über die Niere ausgeschieden. Fluconazol hemmt auch menschliche Leberenzyme (stark CYP2C19 und CYP2C9, mässig CYP3A4) und verursacht dadurch zahlreiche Wechselwirkungen.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Bauchschmerzen, Übelkeit, Erbrechen, Durchfall","Erhöhte Leberwerte (ALT, AST, alkalische Phosphatase)","Hautausschlag"],"gelegentlich":["Anämie (Blutarmut)","Appetitlosigkeit","Schlaflosigkeit, Schläfrigkeit","Krampfanfälle, Schwindel, Kribbeln, Geschmacksstörungen","Verstopfung, Verdauungsbeschwerden, Blähungen, Mundtrockenheit","Cholestase, Gelbsucht, erhöhtes Bilirubin","Juckreiz, Nesselsucht, vermehrtes Schwitzen, fixes Arzneimittelexanthem","Muskelschmerzen, Müdigkeit, Fieber"],"selten":["Agranulozytose, Leukopenie, Neutropenie, Thrombozytopenie","Anaphylaxie und Angioödem","Hypokaliämie (Kaliummangel), erhöhte Blutfette","Zittern (Tremor)","QT-Verlängerung, Torsade de pointes (lebensgefährliche Herzrhythmusstörung)","Leberversagen, Hepatitis, Lebernekrose","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, AGEP), Haarausfall"],"unbekannt":["DRESS (Arzneimittelreaktion mit Eosinophilie und Organbeteiligung)","Nebenniereninsuffizienz"]},"schwangerschaft":"Nicht anwenden, ausser bei schweren oder lebensbedrohlichen Pilzinfektionen. Hohe Dosen (400–800 mg pro Tag) über Wochen im ersten Drittel wurden mit Fehlbildungen in Verbindung gebracht; auch eine Einmaldosis im ersten Drittel ist mit einem leicht erhöhten Fehlgeburtsrisiko assoziiert – bei Scheidenpilz lokale Mittel bevorzugen.","stillzeit":"Geht in ähnlicher Konzentration wie im Blut in die Muttermilch über. Nach einer Einzeldosis von 150 mg kann weiter gestillt werden; bei wiederholter oder hoch dosierter Behandlung wird Stillen nicht empfohlen.","hinweise":["Wegen der langen Halbwertszeit bestehen Wechselwirkungen noch 4–5 Tage nach der letzten Einnahme.","Kann unabhängig von den Mahlzeiten eingenommen werden.","Schwindel oder Krampfanfälle möglich – Vorsicht beim Autofahren.","Bei längerer Behandlung Leberwerte kontrollieren; bei Gelbsucht, dunklem Urin oder starkem Ausschlag ärztlich melden."],"darreichung":["Kapseln","Pulver für Suspension zum Einnehmen","Infusionslösung"]},"flucytosin":{"wirkmechanismus":"Wirkt gegen Hefepilze, indem es in deren Erbgut- und Eiweissbildung eingreift. Flucytosin wird von Pilzzellen über eine Cytosin-Permease aufgenommen und durch das pilzeigene Enzym Cytosin-Desaminase in 5-Fluorouracil umgewandelt. Dieses wird in die RNA eingebaut und hemmt als 5-Fluordesoxyuridinmonophosphat die Thymidylat-Synthase und damit die DNA-Synthese. Menschliche Zellen besitzen kaum Cytosin-Desaminase; Darmbakterien können jedoch 5-Fluorouracil bilden, was zur Toxizität beitragen kann. Wegen rascher Resistenzentwicklung wird Flucytosin nicht allein eingesetzt.","nebenwirkungen":{"unbekannt":["Übelkeit, Erbrechen, Durchfall","Hautausschlag, Juckreiz","Blutbildveränderungen (Leukopenie, Thrombozytopenie, Anämie)","Agranulozytose, aplastische Anämie (schwere Knochenmarkschädigung)","Erhöhte Leberwerte, Hepatitis, Lebernekrose","Verwirrtheit, Halluzinationen, Krampfanfälle, Kopfschmerzen, Schwindel","Herzmuskelschädigung (Kardiotoxizität)","Schwere Hautreaktionen (Einzelfälle)"]},"schwangerschaft":"Im Tierversuch fruchtschädigend; nur bei lebensbedrohlicher Infektion und nach strenger ärztlicher Abwägung anwenden.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Blutbild, Nieren- und Leberwerte werden regelmässig kontrolliert; meist wird auch der Flucytosin-Blutspiegel gemessen.","Angeben, wenn in den letzten 4 Wochen Brivudin (z. B. gegen Gürtelrose) eingenommen wurde."],"darreichung":["Infusionslösung"]},"fludarabin":{"wirkmechanismus":"Hemmt die Vermehrung von Krebszellen und tötet besonders Lymphozyten ab. Fludarabinphosphat ist eine Vorstufe (Prodrug), die im Blut zu 2-Fluoro-ara-A umgewandelt und in der Zelle zum wirksamen Triphosphat (2-Fluoro-ara-ATP) aktiviert wird. Dieses hemmt Ribonukleotid-Reduktase, DNA-Polymerasen, DNA-Primase und DNA-Ligase und damit die DNA-Synthese; zusätzlich wird die RNA-Synthese gestört. So werden auch ruhende Leukämiezellen in den programmierten Zelltod (Apoptose) getrieben.","nebenwirkungen":{"sehrHaeufig":["Infektionen, inkl. opportunistischer Infektionen und Lungenentzündung","Neutropenie, Thrombozytopenie, Anämie (Mangel an Blutzellen)","Husten","Übelkeit, Erbrechen, Durchfall","Fieber, Müdigkeit, Schwäche"],"haeufig":["Myelodysplastisches Syndrom und akute myeloische Leukämie (v. a. nach Vorbehandlung mit alkylierenden Mitteln)","Appetitlosigkeit","Periphere Neuropathie (Kribbeln, Taubheitsgefühl)","Sehstörungen","Mundschleimhautentzündung","Hautausschlag","Ödeme (Wassereinlagerungen), Schüttelfrost, Unwohlsein"],"gelegentlich":["Autoimmunerkrankungen wie autoimmunhämolytische Anämie, Immunthrombozytopenie, Pemphigus","Tumorlysesyndrom","Verwirrtheit","Lungentoxizität (Lungenfibrose, Pneumonitis, Atemnot)","Magen-Darm-Blutungen","Veränderte Leber- und Pankreasenzyme"],"selten":["Koma, Krampfanfälle, Unruhe","Erblindung, Sehnerventzündung","Herzinsuffizienz, Herzrhythmusstörungen","Hautkrebs","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse (schwere Hautreaktionen)","Epstein-Barr-Virus-assoziierte lymphoproliferative Erkrankungen"],"unbekannt":["Progressive multifokale Leukoenzephalopathie (PML, schwere Hirninfektion)","Leukoenzephalopathie (Schädigung der weissen Hirnsubstanz)","Hämorrhagische Zystitis (blutige Blasenentzündung)","Hirnblutung, Lungenblutung"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit anwenden, da Fludarabin im Tierversuch fruchtschädigend wirkt. Frauen und Männer müssen während der Behandlung und mindestens 6 Monate danach zuverlässig verhüten.","stillzeit":"Kontraindiziert.","hinweise":["Blutbild regelmässig kontrollieren; Fieber, Infektzeichen, dunkler Urin oder Gelbfärbung der Haut sofort melden.","Vor Bluttransfusionen das Behandlungsteam informieren: nur bestrahlte Blutprodukte verwenden.","Müdigkeit, Schwäche und Sehstörungen können die Fahrtüchtigkeit beeinträchtigen.","Keine Lebendimpfungen während und nach der Behandlung."],"darreichung":["Injektions- bzw. Infusionslösung"]},"fludrocortison":{"wirkmechanismus":"Ersetzt das Hormon Aldosteron, das bei Nebenniereninsuffizienz fehlt, und sorgt dafür, dass die Niere Salz und Wasser zurückhält. Fludrocortison bindet an Mineralokortikoid-Rezeptoren im Endabschnitt der Nierenkanälchen und steigert dort die Rückgewinnung von Natrium sowie die Ausscheidung von Kalium und Wasserstoffionen. Dadurch normalisieren sich Blutvolumen, Blutdruck und Salzhaushalt. Die mineralokortikoide Wirkung ist sehr stark; die glukokortikoide (entzündungshemmende) Wirkung spielt in den üblichen niedrigen Dosen keine Rolle.","nebenwirkungen":{"unbekannt":["Salz- und Wasserretention mit Ödemen und Gewichtszunahme","Bluthochdruck","Hypokaliämie (Kaliummangel) und hypokaliämische Alkalose","Herzinsuffizienz, Herzvergrösserung","Muskelschwäche","Kopfschmerzen","Bei höheren Dosen glukokortikoidtypische Wirkungen (z. B. Osteoporose, erhöhter Blutzucker, Infektanfälligkeit)","Überempfindlichkeitsreaktionen (Hautausschlag)"]},"schwangerschaft":"Eine notwendige Ersatztherapie bei Nebenniereninsuffizienz wird auch in der Schwangerschaft weitergeführt; Dosis ärztlich überwachen.","stillzeit":"Nur nach ärztlicher Abwägung; eine notwendige Ersatztherapie wird in der Regel weitergeführt.","hinweise":["Nie eigenmächtig absetzen; immer zusammen mit dem verordneten Glukokortikoid (z. B. Hydrocortison) einnehmen.","Notfallausweis für Nebenniereninsuffizienz mitführen; bei Fieber, Erbrechen oder vor Operationen ärztlich die Glukokortikoid-Dosis anpassen lassen.","Regelmässig Blutdruck, Gewicht, Kalium und Natrium kontrollieren: Salzhunger und Schwindel beim Aufstehen sprechen für eine zu tiefe, Ödeme und Bluthochdruck für eine zu hohe Dosis."],"darreichung":["Tabletten"]},"flumazenil":{"wirkmechanismus":"Hebt die beruhigende, schlafmachende und atemdämpfende Wirkung von Benzodiazepinen auf. Flumazenil ist ein Imidazobenzodiazepin, das die Benzodiazepin-Bindungsstelle am GABA-A-Rezeptor kompetitiv besetzt, ohne sie nennenswert zu aktivieren. Es verdrängt so Benzodiazepine und auch Z-Substanzen wie Zolpidem und Zopiclon. Die Wirkung tritt innert 1–2 Minuten ein, hält aber wegen der kurzen Halbwertszeit von etwa einer Stunde oft kürzer an als die des Benzodiazepins.","nebenwirkungen":{"sehrHaeufig":["Übelkeit"],"haeufig":["Angst, Stimmungsschwankungen, Schlaflosigkeit","Schwindel, Kopfschmerzen, Zittern, Unruhe","Doppelbilder, vermehrter Tränenfluss","Herzklopfen, Hitzewallungen, Blutdruckabfall","Erbrechen, Schluckauf, Schwitzen","Müdigkeit, Schmerzen an der Injektionsstelle"],"gelegentlich":["Krampfanfälle (v. a. bei Epilepsie oder schwerer Leberinsuffizienz)","Herzrasen, verlangsamter Puls, Extrasystolen","Atemnot, Husten","Hörstörungen","Frösteln"],"selten":["Vorübergehender Blutdruckanstieg"],"unbekannt":["Überempfindlichkeitsreaktionen bis zur Anaphylaxie","Entzugssymptome nach Benzodiazepin-Langzeitanwendung","Panikattacken bei Menschen mit Panikstörung"]},"schwangerschaft":"Erfahrungen fehlen; nur bei klarer Notwendigkeit anwenden. Im Notfall ist die Anwendung nicht kontraindiziert.","stillzeit":"Ob Flumazenil in die Muttermilch übergeht, ist nicht bekannt; im Notfall ist die Anwendung nicht kontraindiziert.","hinweise":["Da die Benzodiazepinwirkung zurückkehren kann, bleiben Patientinnen und Patienten nach der Gabe unter Überwachung.","Nach der Behandlung mindestens 24 Stunden nicht Auto fahren, keine Maschinen bedienen und keinen Alkohol trinken.","Wird nur von Fachpersonen im Spital oder in der Notfallmedizin angewendet."],"darreichung":["Injektionslösung"]},"flumetason":{"wirkmechanismus":"Dämpft Entzündung, Juckreiz und Schwellung der Haut. Flumetasonpivalat ist ein fluoriertes Glukokortikoid, das an Glukokortikoidrezeptoren in den Hautzellen bindet und die Bildung entzündungsfördernder Botenstoffe hemmt; zudem verengt es die Blutgefässe und bremst eine übermässige Zellteilung. In den Kombinationen wirkt Clioquinol gegen Bakterien und Pilze, Salicylsäure löst Schuppen und erleichtert das Eindringen des Kortikoids.","nebenwirkungen":{"unbekannt":["Brennen, Juckreiz, Reizung oder Trockenheit der Haut","Allergische Kontaktdermatitis","Hautverdünnung (Atrophie), Dehnungsstreifen und erweiterte Äderchen (Teleangiektasien) bei längerer Anwendung","Periorale Dermatitis, steroidbedingte Akne, Haarbalgentzündung (Follikulitis)","Verschleierung oder Ausbreitung von Hautinfektionen","Gelbliche Verfärbung von Haut, Haaren, Nägeln und Wäsche (Clioquinol)","Unterdrückung der Nebennierenfunktion bei grossflächiger Anwendung","Verschwommenes Sehen"]},"schwangerschaft":"Nur nach ärztlicher Abwägung, kurzfristig und kleinflächig anwenden; nicht unter luftdichten Verbänden.","stillzeit":"Nur nach ärztlicher Abwägung und kleinflächig; nicht im Brustbereich auftragen.","hinweise":["Dünn und nur so lange wie verordnet anwenden; nicht unter luftdichten Verbänden.","Clioquinol färbt Haut, Haare und Textilien gelblich – Kleidung und Wäsche schützen.","Die Anwendung vor Schilddrüsenuntersuchungen angeben (Clioquinol kann Testergebnisse verfälschen)."],"darreichung":["Creme","Salbe","Ohrentropfen"]},"flunitrazepam":{"wirkmechanismus":"Macht rasch und stark schläfrig, indem es die Wirkung eines hemmenden Botenstoffs im Gehirn verstärkt. Flunitrazepam bindet mit hoher Affinität an die Benzodiazepin-Bindungsstelle des GABA-A-Rezeptors und verstärkt die hemmende Wirkung von GABA; schon kleine Mengen wirken stark beruhigend, muskelentspannend und gedächtnisdämpfend. Es wird in der Leber unter Beteiligung von CYP3A4 und CYP2C19 abgebaut; die Halbwertszeit beträgt etwa 16–35 Stunden.","nebenwirkungen":{"haeufig":["Müdigkeit und Benommenheit am Folgetag","Schwindel","Gangunsicherheit (Ataxie)","Verminderte Konzentration und Reaktionsfähigkeit"],"unbekannt":["Anterograde Amnesie (Erinnerungslücken für die Zeit nach der Einnahme)","Verwirrtheit, besonders bei älteren Menschen","Paradoxe Reaktionen (Unruhe, Erregung, Aggressivität, Albträume, Halluzinationen)","Muskelschwäche und Stürze","Kopfschmerzen, Sehstörungen","Atemdepression (Atemdämpfung)","Abhängigkeit, Entzugserscheinungen und Rebound-Schlaflosigkeit beim Absetzen","Blutdruckabfall"]},"schwangerschaft":"Nicht anwenden, ausser bei zwingender Notwendigkeit nach ärztlicher Abwägung. Bei Einnahme gegen Ende der Schwangerschaft drohen beim Neugeborenen Atemprobleme, Muskelschlaffheit, Unterkühlung und Entzugssymptome.","stillzeit":"Flunitrazepam geht in die Muttermilch über und kann beim Säugling zu Schläfrigkeit und Trinkschwäche führen – nicht anwenden bzw. abstillen.","hinweise":["Nur kurzfristig und in der tiefsten wirksamen Dosis einnehmen; sehr hohes Abhängigkeitsrisiko.","Tabletten sicher und für Dritte unzugänglich aufbewahren und nie weitergeben (Missbrauchsgefahr).","Fahrtüchtigkeit auch am nächsten Tag eingeschränkt; keinen Alkohol trinken.","Nach längerer Einnahme nicht abrupt absetzen, sondern nach ärztlicher Anweisung schrittweise ausschleichen."],"darreichung":["Filmtabletten"]},"fluocinonid":{"wirkmechanismus":"Dämpft Entzündung, Rötung, Schwellung und Juckreiz der Haut. Fluocinonid ist ein fluoriertes, stark wirksames Glukokortikoid: Es bindet an Glukokortikoid-Rezeptoren in den Hautzellen und hemmt die Bildung entzündungsfördernder Botenstoffe wie Prostaglandine, Leukotriene und Zytokine. Zusätzlich verengt es die Blutgefässe der Haut und bremst die Zellteilung in der Oberhaut. Bei grossflächiger oder langer Anwendung kann so viel Wirkstoff durch die Haut aufgenommen werden, dass Wirkungen im ganzen Körper auftreten.","nebenwirkungen":{"unbekannt":["Brennen, Juckreiz oder Reizung an der Auftragsstelle","Hautatrophie (Hautverdünnung), Teleangiektasien (erweiterte Äderchen), Dehnungsstreifen (Striae)","Steroidakne, periorale Dermatitis (Ausschlag um den Mund)","Hellere Hautstellen (Hypopigmentierung), vermehrte Behaarung","Allergische Kontaktdermatitis","Sekundäre Hautinfektionen durch Bakterien oder Pilze","Verschwommenes Sehen (z. B. durch Chorioretinopathie)","Bei grossflächiger oder langer Anwendung: Unterdrückung der Nebennierenrinde, Cushing-Syndrom, bei Kindern Wachstumsverzögerung"]},"schwangerschaft":"Nur nach ärztlicher Abwägung, kleinflächig und kurzzeitig; nicht grossflächig, nicht langfristig und nicht unter luftdichten Verbänden anwenden.","stillzeit":"Kleinflächige, kurzzeitige Anwendung nach ärztlicher Abwägung möglich; nicht im Brustbereich auftragen, damit der Säugling den Wirkstoff nicht aufnimmt.","hinweise":["Dünn auftragen und nur so lange wie nötig anwenden; im Gesicht nur auf ärztliche Anweisung.","Nicht in die Augen bringen; nach dem Auftragen die Hände waschen.","Keine luftdichten Verbände ohne ärztliche Anweisung.","Nach längerer Anwendung nicht abrupt absetzen, sondern schrittweise reduzieren (Rückfallgefahr)."],"darreichung":["Creme","Salbe","Lösung zur Anwendung auf der Kopfhaut"]},"fluocortolon":{"wirkmechanismus":"Lindert Entzündung, Schwellung und Juckreiz am After. Fluocortolon ist ein stark wirksames Glukokortikoid, das über den Glukokortikoid-Rezeptor die Bildung entzündungsfördernder Botenstoffe (z. B. Prostaglandine, Zytokine) hemmt und die Durchlässigkeit kleiner Gefässe vermindert. In den Kombipräparaten sorgt ein Lokalanästhetikum (Lidocain bzw. Cinchocain) für eine rasche Schmerzlinderung.","nebenwirkungen":{"unbekannt":["Lokales Brennen oder Reizung","Allergische Hautreaktionen","Bei Anwendung über mehrere Wochen: Hautverdünnung (Atrophie), Dehnungsstreifen (Striae), erweiterte Äderchen (Teleangiektasien)","Verschwommenes Sehen (Kortison-Klasseneffekt)"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung, besonders im ersten Schwangerschaftsdrittel; dann kurz und kleinflächig anwenden.","stillzeit":"Kurzfristige Anwendung nach ärztlicher Abwägung möglich; es gelangen nur geringe Mengen in den Körper.","hinweise":["Nicht länger als nötig und ohne ärztliche Kontrolle nicht über mehrere Wochen anwenden.","Zäpfchen nach dem Stuhlgang einführen; durch Wärme weich gewordene Zäpfchen kurz kühlen.","Kann die Reissfestigkeit von Latexkondomen vermindern.","Blut im Stuhl immer ärztlich abklären lassen."],"darreichung":["Rektalcreme","Salbe","Zäpfchen"]},"fluorouracil":{"wirkmechanismus":"Hemmt die Teilung schnell wachsender Zellen, indem es die Herstellung von Erbgut stört. Fluorouracil wird in der Zelle zu FdUMP umgewandelt, das die Thymidylat-Synthase blockiert und so die DNA-Synthese hemmt; als FUTP wird es zudem fehlerhaft in die RNA eingebaut. Folinsäure verstärkt die Hemmung der Thymidylat-Synthase. Der Abbau erfolgt über das Enzym Dihydropyrimidin-Dehydrogenase (DPD); bei DPD-Mangel drohen schwere, teils tödliche Vergiftungen. Auf der Haut zerstört es gezielt die sich rasch teilenden, krankhaft veränderten Zellen.","nebenwirkungen":{"sehrHaeufig":["Knochenmarkhemmung (Neutropenie bis Agranulozytose, Thrombozytopenie, Anämie)","Entzündungen der Schleimhäute in Mund, Speiseröhre und Darm","Durchfall, Übelkeit, Erbrechen, Appetitlosigkeit","Haarausfall","Hand-Fuss-Syndrom (schmerzhafte Rötung von Handflächen und Fusssohlen)","Müdigkeit, Schwäche","Creme/Lösung: Rötung, Brennen, Schmerzen, Krusten und Erosionen an der behandelten Haut (erwartete Reaktion)"],"haeufig":["Fieber bei Neutropenie (febrile Neutropenie)","Brustschmerzen und Durchblutungsstörungen des Herzens (EKG-Veränderungen)"],"gelegentlich":["Herzrhythmusstörungen, Herzinfarkt, Herzmuskelentzündung, Herzinsuffizienz","Magen-Darm-Geschwüre und -Blutungen","Sepsis (Blutvergiftung), Flüssigkeitsmangel","Augenbeschwerden (Tränenfluss, verschwommenes Sehen, Augenzittern)","Kopfschmerzen, Schwindel, Bewegungsstörungen","Hautausschlag, Lichtempfindlichkeit, Pigment- und Nagelveränderungen"],"selten":["Anaphylaxie (schwere allergische Reaktion)"],"sehrSelten":["Leukenzephalopathie (Schädigung der weissen Hirnsubstanz)","Herzstillstand, plötzlicher Herztod","Akutes Nierenversagen"],"unbekannt":["Hyperammonämische Enzephalopathie (Verwirrtheit durch erhöhtes Ammoniak)"]},"schwangerschaft":"Kontraindiziert, auch als Creme oder Lösung (fruchtschädigend). Frauen und Männer müssen während und einige Monate nach einer Behandlung zuverlässig verhüten.","stillzeit":"Kontraindiziert.","hinweise":["Vor einer Infusionstherapie wird auf einen DPD-Mangel getestet.","Kein Brivudin (Gürtelrosemittel) während der Behandlung sowie in den 4 Wochen davor und danach – auch nicht bei Anwendung der Creme.","Creme nur auf die betroffenen Hautstellen auftragen, danach Hände waschen; Sonne meiden. Die gewollte Hautentzündung heilt nach Behandlungsende ab.","Bei starkem Durchfall, Mundgeschwüren, Fieber oder Brustschmerzen sofort ärztlich melden."],"darreichung":["Creme","Lösung zum Auftragen auf die Haut","Injektions- bzw. Infusionslösung"]},"fluoxetin":{"wirkmechanismus":"Hellt die Stimmung auf und vermindert Zwangsgedanken und Essattacken, indem es die Menge des Botenstoffs Serotonin zwischen den Nervenzellen erhöht. Fluoxetin hemmt selektiv den Serotonin-Transporter und damit die Wiederaufnahme von Serotonin in die Nervenzelle. Fluoxetin und sein wirksames Abbauprodukt Norfluoxetin haben sehr lange Halbwertszeiten (Tage bis Wochen), weshalb Wirkung und Wechselwirkungen nach dem Absetzen noch wochenlang anhalten. Fluoxetin hemmt zudem stark das Abbauenzym CYP2D6.","nebenwirkungen":{"sehrHaeufig":["Schlaflosigkeit","Kopfschmerzen","Übelkeit, Durchfall","Müdigkeit"],"haeufig":["Appetitlosigkeit, Gewichtsabnahme","Angst, Nervosität, Unruhe, ungewöhnliche Träume","Verminderte Libido, Erektions- und Ejakulationsstörungen","Schwindel, Schläfrigkeit, Zittern, Konzentrations- und Geschmacksstörungen","Verschwommenes Sehen, Herzklopfen, Hitzewallungen","Mundtrockenheit, Erbrechen, Verdauungsbeschwerden","Hautausschlag, Juckreiz, Nesselsucht, vermehrtes Schwitzen","Gelenkschmerzen, häufiges Wasserlassen, gynäkologische Blutungen"],"gelegentlich":["Suizidgedanken und suizidales Verhalten","Gehobene Stimmung, Depersonalisation, Zähneknirschen (Bruxismus)","Muskelzuckungen, Gangunsicherheit, Gedächtnisstörungen","Erweiterte Pupillen (Mydriasis), Ohrgeräusche (Tinnitus)","Blutdruckabfall","Atemnot, Nasenbluten","Magen-Darm-Blutungen, Schluckbeschwerden","Haarausfall, Neigung zu Blutergüssen"],"selten":["Hyponatriämie (Natriummangel)","Manie, Halluzinationen, Panikattacken, Aggressivität, Verwirrtheit","Krampfanfälle, Akathisie (Bewegungsunruhe), Serotoninsyndrom","QT-Verlängerung, ventrikuläre Herzrhythmusstörungen inkl. Torsade de pointes","Leberentzündung (Hepatitis)","Angioödem, Lichtempfindlichkeit, schwere Hautreaktionen (Erythema multiforme, Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Blutbildveränderungen (Thrombozytopenie, Neutropenie), anaphylaktische Reaktionen","Milchfluss (Galaktorrhö), Priapismus (Dauererektion), Harnverhalt"],"unbekannt":["Erhöhtes Risiko für Knochenbrüche","Nachblutungen nach der Geburt (bei Einnahme im letzten Monat der Schwangerschaft)"]},"schwangerschaft":"Nur nach sorgfältiger ärztlicher Abwägung: nach Einnahme im ersten Drittel wurde ein leicht erhöhtes Risiko für Herzfehler beobachtet, bei Einnahme in der Spätschwangerschaft sind beim Neugeborenen Anpassungsstörungen und Lungenhochdruck (PPHN) möglich. Nicht eigenmächtig absetzen.","stillzeit":"Fluoxetin und Norfluoxetin gehen in die Muttermilch über, beim Säugling wurden Nebenwirkungen beobachtet; ist eine Behandlung nötig, soll abgestillt werden – wird trotzdem weiter gestillt, nur mit der tiefsten wirksamen Dosis.","hinweise":["Die Wirkung setzt nach 2–4 Wochen ein; zunehmende Unruhe oder Suizidgedanken in den ersten Wochen sofort ärztlich melden.","Wegen der langen Wirkdauer bestehen Wechselwirkungen noch bis zu 5 Wochen nach dem Absetzen (z. B. vor Beginn eines MAO-Hemmers).","Nicht abrupt absetzen, auch wenn Absetzsymptome seltener sind als bei anderen SSRI.","Kann die Fahrtüchtigkeit beeinträchtigen; Alkohol meiden."],"darreichung":["Kapseln","Tabletten"]},"flupentixol":{"wirkmechanismus":"Mildert Wahn, Halluzinationen und Denkstörungen; in niedriger Dosis wirkt es eher antriebssteigernd als dämpfend. Flupentixol ist ein hochpotentes Thioxanthen-Neuroleptikum, das Dopamin-D1- und D2-Rezeptoren blockiert. Histamin-, Muskarin- und Alpha-1-Rezeptoren werden nur schwach beeinflusst. Als Depotform (Flupentixoldecanoat) wird der Wirkstoff aus dem Muskel über 2–4 Wochen langsam freigesetzt.","nebenwirkungen":{"sehrHaeufig":["Schläfrigkeit","Akathisie (Sitzunruhe), Hyperkinesie oder Hypokinesie (vermehrte bzw. verminderte Beweglichkeit)","Mundtrockenheit"],"haeufig":["Zittern, Dystonie (Muskelverkrampfungen), Schwindel, Kopfschmerzen","Herzrasen, Herzklopfen","Sehstörungen (Akkommodationsstörungen)","Vermehrter Speichelfluss, Verstopfung, Erbrechen, Verdauungsbeschwerden, Durchfall","Störungen beim Wasserlassen, Harnverhalt","Vermehrtes Schwitzen, Juckreiz","Gewichtszunahme, Schlaflosigkeit, Nervosität, verminderte Libido"],"gelegentlich":["Spätdyskinesien (unwillkürliche Bewegungen), Parkinsonismus","Krampfanfälle","Blickkrämpfe","Blutdruckabfall, Hitzewallungen","Hautausschlag, Lichtempfindlichkeit","Veränderte Leberwerte","Ejakulations- und Erektionsstörungen","Verwirrtheit"],"selten":["Blutbildveränderungen bis Agranulozytose","Erhöhter Prolaktinspiegel, Milchfluss, Brustvergrösserung beim Mann, Ausbleiben der Regel","Hyperglykämie (erhöhter Blutzucker)","Malignes neuroleptisches Syndrom (Fieber, Muskelsteifigkeit, Bewusstseinsstörung)","Anaphylaxie (schwere allergische Reaktion)"],"sehrSelten":["Gelbsucht","Venöse Thromboembolien (Blutgerinnsel)"],"unbekannt":["QT-Verlängerung, Torsade de pointes (lebensgefährliche Herzrhythmusstörung), plötzlicher Herztod"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Bei Anwendung im letzten Drittel können beim Neugeborenen Bewegungsstörungen und Entzugssymptome auftreten.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Stillen ist nach ärztlicher Abwägung möglich, das Kind sollte beobachtet werden.","hinweise":["Kann die Reaktionsfähigkeit beeinträchtigen – Vorsicht beim Autofahren, Alkohol meiden.","Depotspritzen regelmässig nach Plan erhalten; ausgelassene Termine erhöhen die Rückfallgefahr.","Bei Fieber mit Muskelsteifigkeit und Verwirrtheit sofort ärztliche Hilfe holen (malignes neuroleptisches Syndrom)."],"darreichung":["Filmtabletten","Depot-Injektionslösung (intramuskulär)"]},"flurazepam":{"wirkmechanismus":"Macht schläfrig und beruhigt, indem es die Wirkung eines hemmenden Botenstoffs im Gehirn verstärkt. Flurazepam bindet an die Benzodiazepin-Bindungsstelle des GABA-A-Rezeptors und verstärkt so die hemmende Wirkung von GABA (vermehrter Chlorideinstrom in die Nervenzelle). In der Leber entsteht daraus der wirksame Metabolit N-Desalkylflurazepam mit einer sehr langen Halbwertszeit von mehreren Tagen, bei älteren Menschen noch länger. Deshalb reichert sich die Wirkung bei wiederholter Einnahme an, und Müdigkeit am Folgetag ist häufig.","nebenwirkungen":{"haeufig":["Müdigkeit und Benommenheit am Folgetag (Überhangeffekt)","Schwindel","Gangunsicherheit (Ataxie)","Verminderte Konzentration und Reaktionsfähigkeit"],"unbekannt":["Anterograde Amnesie (Erinnerungslücken für die Zeit nach der Einnahme)","Verwirrtheit, besonders bei älteren Menschen","Paradoxe Reaktionen (Unruhe, Erregung, Aggressivität, Albträume, Halluzinationen)","Muskelschwäche und Stürze","Kopfschmerzen, Doppelbilder","Atemdepression (Atemdämpfung)","Abhängigkeit, Entzugserscheinungen und Rebound-Schlaflosigkeit beim Absetzen","Überempfindlichkeitsreaktionen der Haut"]},"schwangerschaft":"Nicht anwenden, ausser bei zwingender Notwendigkeit nach ärztlicher Abwägung. Bei Einnahme gegen Ende der Schwangerschaft drohen beim Neugeborenen Atemprobleme, Muskelschlaffheit, Unterkühlung und Entzugssymptome.","stillzeit":"Flurazepam und seine lang wirksamen Abbauprodukte gehen in die Muttermilch über und können sich beim Säugling anreichern – nicht anwenden bzw. abstillen.","hinweise":["Nur kurzfristig einnehmen (in der Regel höchstens wenige Wochen); bei längerer Einnahme droht Abhängigkeit.","Wegen der sehr langen Wirkdauer ist die Fahrtüchtigkeit oft auch am nächsten Tag eingeschränkt; keinen Alkohol trinken.","Nach längerer Einnahme nicht abrupt absetzen, sondern nach ärztlicher Anweisung schrittweise ausschleichen.","Ältere Menschen: erhöhte Sturzgefahr in der Nacht und am Folgetag."],"darreichung":["Tabletten"]},"flurbiprofen":{"wirkmechanismus":"Lindert Halsschmerzen und Schwellung direkt im Rachen. Flurbiprofen hemmt die Cyclooxygenasen und damit die Bildung von Prostaglandinen, die Entzündung und Schmerz vermitteln. Die Wirkung setzt nach etwa 30 Minuten ein und hält einige Stunden an. Ein Teil des Wirkstoffs wird verschluckt und gelangt ins Blut.","nebenwirkungen":{"haeufig":["Schwindel, Kopfschmerzen","Reizung, Wärmegefühl oder Brennen im Mund und Rachen","Kribbeln im Mund","Übelkeit, Durchfall","Mundgeschwüre (Aphthen), Mundschmerzen"],"gelegentlich":["Schläfrigkeit, Schlaflosigkeit","Verschlechterung eines Asthmas, Bronchospasmus, Atemnot","Bläschen im Mund- und Rachenraum, Taubheitsgefühl im Rachen","Bauchschmerzen, Blähungen, Verstopfung, Dyspepsie, Mundtrockenheit, Erbrechen","Geschmacksstörungen","Hautausschlag, Juckreiz","Fieber"],"selten":["Anaphylaxie (schwere allergische Reaktion)"],"unbekannt":["Anämie, Thrombozytopenie","Ödeme, Bluthochdruck, Herzinsuffizienz","Hepatitis","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Angioödem"]},"schwangerschaft":"Im 1. und 2. Drittel nur nach ärztlicher Rücksprache; im letzten Drittel kontraindiziert.","stillzeit":"Geht nur in sehr geringen Mengen in die Muttermilch über; die Anwendung in der Stillzeit wird dennoch nicht empfohlen.","hinweise":["Lutschtablette langsam im Mund zergehen lassen und dabei im Mund bewegen; höchstens 5 Lutschtabletten in 24 Stunden und höchstens 3 Tage anwenden.","Bei Halsschmerzen mit hohem Fieber, Eiter, Atemnot oder Schluckbeschwerden ärztlich abklären lassen.","Nicht gleichzeitig mit anderen NSAR-Schmerzmitteln (z. B. Ibuprofen, Diclofenac) anwenden."],"darreichung":["Lutschtabletten"]},"flutamid":{"wirkmechanismus":"Blockiert die Wirkung männlicher Hormone (Androgene) an den Prostatazellen, die das Wachstum von Prostatakrebs fördern. Flutamid und sein aktiver Hauptmetabolit 2-Hydroxyflutamid hemmen kompetitiv die Bindung von Testosteron und Dihydrotestosteron an den Androgenrezeptor. Allein gegeben steigen Testosteron und Östradiol gegenregulatorisch an; darum wird Flutamid meist mit einem Hormonentzug (GnRH-Analogon oder Orchiektomie) zur kompletten Androgenblockade kombiniert.","nebenwirkungen":{"sehrHaeufig":["Gynäkomastie (Brustvergrösserung beim Mann) und Brustspannen, teils mit Milchfluss"],"haeufig":["Durchfall, Übelkeit, Erbrechen","Gesteigerter Appetit","Schlaflosigkeit, Müdigkeit","Vorübergehend erhöhte Leberwerte","Hitzewallungen, Libidoverlust, Erektionsstörungen"],"selten":["Hepatitis (Leberentzündung), Gelbsucht"],"sehrSelten":["Leberversagen, Lebernekrose, hepatische Enzephalopathie (teils tödlich)","Methämoglobinämie (verminderte Sauerstoffbindung im Blut), hämolytische Anämie","Lichtempfindlichkeit der Haut (Photosensibilität)"],"unbekannt":["QT-Verlängerung","Bernsteinfarbene bis gelbgrüne Verfärbung des Urins"]},"schwangerschaft":"Nicht zutreffend – Flutamid ist nur für Männer bestimmt; Frauen dürfen es nicht einnehmen (Schädigung eines männlichen Kindes möglich).","stillzeit":"Nicht zutreffend – nicht zur Anwendung bei Frauen bestimmt.","hinweise":["Bei dunklem Urin, Gelbfärbung von Haut oder Augen, Juckreiz, Appetitlosigkeit oder Oberbauchschmerzen sofort ärztlich melden.","Der Urin kann sich bernsteinfarben bis gelbgrün verfärben (harmlos).","Sonne und Solarium meiden; Alkohol einschränken."],"darreichung":["Tabletten"]},"fluticason":{"wirkmechanismus":"Hemmt die Entzündung direkt am Ort der Anwendung – in den Bronchien, in der Nasenschleimhaut oder in der Haut. Fluticasonpropionat ist ein stark wirksames Glukokortikoid mit sehr hoher Affinität zum Glukokortikoid-Rezeptor; es vermindert die Bildung entzündungsfördernder Botenstoffe und die Einwanderung von Entzündungszellen wie eosinophilen Granulozyten und Mastzellen. Verschluckter Wirkstoff wird in der Leber über CYP3A4 fast vollständig abgebaut (orale Bioverfügbarkeit unter 1 %), weshalb die Wirkung im ganzen Körper normalerweise gering bleibt – starke CYP3A4-Hemmer heben diesen Schutz auf.","nebenwirkungen":{"sehrHaeufig":["Pilzbefall von Mund und Rachen (Soor) bei Inhalation","Nasenbluten (Nasenspray)"],"haeufig":["Heiserkeit","Blaue Flecken (Hämatome)","Lungenentzündung (Pneumonie) bei COPD-Patienten","Nasenspray: Kopfschmerzen, unangenehmer Geschmack oder Geruch, trockene und gereizte Nase und Rachen","Creme/Salbe: Juckreiz"],"gelegentlich":["Allergische Hautreaktionen","Creme/Salbe: Brennen der Haut"],"selten":["Pilzbefall der Speiseröhre (Soor-Ösophagitis)"],"sehrSelten":["Anaphylaxie und Angioödem (schwere allergische Reaktionen)","Paradoxer Bronchospasmus (Verkrampfung der Atemwege direkt nach dem Inhalieren)","Kortison-Wirkungen im ganzen Körper: Cushing-Syndrom, Nebennierenschwäche, Wachstumsverzögerung bei Kindern, Abnahme der Knochendichte","Grauer und grüner Star (Katarakt, Glaukom)","Erhöhter Blutzucker","Angst, Schlafstörungen, Verhaltensänderungen wie Unruhe und Reizbarkeit (vor allem bei Kindern)","Durchbruch der Nasenscheidewand (Nasenspray)","Creme/Salbe: Hautverdünnung, Dehnungsstreifen, erweiterte Äderchen"],"unbekannt":["Depression, Aggressivität","Verschwommenes Sehen (Chorioretinopathie)"]},"schwangerschaft":"Nach ärztlicher Abwägung möglich. Bei Inhalation und Nasenspray gelangt nur wenig Wirkstoff in den Körper; eine gute Asthmakontrolle ist für Mutter und Kind wichtig.","stillzeit":"Der Übertritt in die Muttermilch ist beim Menschen nicht untersucht; inhalativ und nasal in üblicher Dosis nach Abwägung vertretbar, da kaum Wirkstoff ins Blut gelangt. Creme/Salbe nicht auf die Brust auftragen.","hinweise":["Nach dem Inhalieren den Mund ausspülen oder etwas essen – beugt Mundsoor und Heiserkeit vor.","Regelmässig anwenden, auch wenn keine Beschwerden bestehen; die volle Wirkung tritt erst nach einigen Tagen ein.","Nicht verwechseln mit Fluticasonfuroat (z. B. Avamys, Relvar, Trelegy) – eigener Wirkstoff mit anderer Dosierung.","Creme/Salbe dünn auftragen und im Gesicht nur kurzfristig anwenden."],"darreichung":["Dosieraerosol","Pulverinhalator (Diskus)","Nasenspray","Creme","Salbe"]},"fluticasonfuroat":{"wirkmechanismus":"Hemmt die allergische Entzündung der Schleimhaut. Fluticasonfuroat ist ein stark wirksames synthetisches Glukokortikoid, das an den Glukokortikoidrezeptor bindet und die Bildung entzündungsfördernder Botenstoffe sowie das Einwandern von Entzündungszellen unterdrückt. Verschluckter Wirkstoff wird in der Leber über CYP3A4 fast vollständig abgebaut, deshalb gelangt nur sehr wenig in den Kreislauf. Die volle Wirkung entwickelt sich über einige Tage.","nebenwirkungen":{"sehrHaeufig":["Nasenbluten (meist leicht)"],"haeufig":["Kopfschmerzen","Geschwüre der Nasenschleimhaut"],"gelegentlich":["Schmerzen, Brennen, Reizung oder Trockenheit in der Nase"],"sehrSelten":["Überempfindlichkeitsreaktionen bis Anaphylaxie, Angioödem, Hautausschlag, Nesselsucht"],"unbekannt":["Wachstumsverzögerung bei Kindern","Verschwommenes Sehen, Katarakt, Glaukom","Durchbruch der Nasenscheidewand (Septumperforation)"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; bei empfohlener Dosierung gelangt nur sehr wenig Wirkstoff in den Kreislauf.","stillzeit":"Nur nach ärztlicher Abwägung; der Übergang in die Muttermilch ist nicht untersucht.","hinweise":["Vor Gebrauch kräftig schütteln und regelmässig anwenden – die volle Wirkung tritt erst nach einigen Tagen ein.","Nach Besserung auf die niedrigste wirksame Dosis reduzieren.","Eine Ritonavir- oder Cobicistat-haltige HIV-Therapie vor Behandlungsbeginn ärztlich angeben."],"darreichung":["Nasenspray (Suspension)","Pulver zur Inhalation (nur in Kombinationspräparaten)"]},"fluticasonfuroat-umeclidinium-vilanterol":{"wirkmechanismus":"Kombiniert Entzündungshemmung mit doppelter Bronchienerweiterung. Fluticasonfuroat ist ein stark wirksames Glukokortikoid, das in der Bronchialschleimhaut Entzündungsbotenstoffe und Entzündungszellen vermindert. Umeclidinium blockiert langanhaltend die Muskarinrezeptoren der Bronchialmuskulatur und hemmt so die Acetylcholin-Wirkung; Vilanterol stimuliert die Beta-2-Rezeptoren und entspannt die Muskulatur. Alle drei Wirkstoffe wirken etwa 24 Stunden.","nebenwirkungen":{"haeufig":["Lungenentzündung (Pneumonie)","Infekte der oberen Atemwege, Bronchitis, Rachen- und Nasennebenhöhlenentzündung, Grippe","Mundsoor (Pilzinfektion in Mund und Rachen)","Harnwegsinfekte","Kopfschmerzen","Husten, Schmerzen in Mund und Rachen","Verstopfung (Obstipation)","Gelenk- und Rückenschmerzen"],"gelegentlich":["Virale Atemwegsinfekte","Herzrhythmusstörungen: Vorhofflimmern, Herzrasen (Tachykardie)","Heiserkeit (Dysphonie)","Mundtrockenheit","Geschmacksstörungen","Knochenbrüche"],"selten":["Überempfindlichkeitsreaktionen: Anaphylaxie, Angioödem, Nesselsucht, Ausschlag","Angst, Zittern (Tremor)","Augenschmerzen, Glaukom, erhöhter Augeninnendruck","Herzklopfen","Harnverhalt, Schmerzen beim Wasserlösen","Muskelkrämpfe"],"unbekannt":["Verschwommensehen","Schwindel","Systemische Kortisonwirkungen bei Langzeitgebrauch (Nebennierenunterdrückung, Abnahme der Knochendichte, grauer Star)"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur anwenden, wenn der Nutzen für die Mutter das mögliche Risiko für das Kind klar überwiegt.","stillzeit":"Nicht bekannt, ob die Wirkstoffe in die Muttermilch übergehen; ein Risiko für den Säugling ist nicht auszuschliessen – ärztliche Abwägung.","hinweise":["Einmal täglich zur gleichen Zeit inhalieren; nicht zur Behandlung akuter Atemnot.","Nach dem Inhalieren den Mund mit Wasser ausspülen, ohne zu schlucken – beugt Mundsoor und Heiserkeit vor.","Bei Fieber, Schüttelfrost, vermehrtem oder verfärbtem Auswurf oder zunehmender Atemnot rasch ärztlich abklären (Lungenentzündung).","Bei Augenschmerzen, verschwommenem Sehen oder Problemen beim Wasserlösen ärztlich abklären lassen."],"darreichung":["Pulver zur Inhalation (Ellipta-Inhalator)"]},"fluvastatin":{"wirkmechanismus":"Senkt das LDL-Cholesterin, indem es die Cholesterinbildung in der Leber hemmt. Fluvastatin hemmt kompetitiv die HMG-CoA-Reduktase, das Schlüsselenzym der Cholesterinsynthese. Die Leberzellen bilden daraufhin mehr LDL-Rezeptoren und holen vermehrt LDL-Cholesterin aus dem Blut; auch die Triglyceride sinken etwas. Fluvastatin wird überwiegend über CYP2C9 abgebaut und ist deshalb wenig anfällig für CYP3A4-Wechselwirkungen.","nebenwirkungen":{"haeufig":["Schlafstörungen","Kopfschmerzen","Dyspepsie (Verdauungsbeschwerden), Bauchschmerzen","Übelkeit"],"selten":["Überempfindlichkeitsreaktionen wie Hautausschlag und Nesselsucht","Myalgie (Muskelschmerzen), Muskelschwäche, Myopathie"],"sehrSelten":["Rhabdomyolyse (Muskelzerfall), Myositis","Hepatitis (Leberentzündung)","Pankreatitis","Angioödem, Gesichtsschwellung","Thrombozytopenie (Mangel an Blutplättchen)","Vaskulitis, Lupus-ähnliche Reaktionen","Kribbeln, Taubheitsgefühl, periphere Neuropathie"],"unbekannt":["Immunvermittelte nekrotisierende Myopathie","Diabetes mellitus","Interstitielle Lungenerkrankung","Depression, Albträume","Gedächtnisstörungen","Erektionsstörungen","Myasthenia gravis"]},"schwangerschaft":"Kontraindiziert; bei Eintritt einer Schwangerschaft sofort absetzen.","stillzeit":"Kontraindiziert, da Fluvastatin in die Muttermilch übergeht.","hinweise":["Ungeklärte Muskelschmerzen, -schwäche oder -krämpfe, besonders mit Fieber oder dunklem Urin, sofort ärztlich melden.","Leberwerte vor Beginn und bei Bedarf kontrollieren.","Kapseln am Abend, Retardtabletten zu beliebiger Tageszeit unzerkaut einnehmen.","Eine Behandlung mit Fusidinsäure-Tabletten oder -Infusionen immer der Ärztin oder dem Arzt mitteilen."],"darreichung":["Kapseln","Retardtabletten"]},"fluvoxamin":{"wirkmechanismus":"Hebt die Stimmung und vermindert Zwangsgedanken, indem es die Konzentration des Botenstoffs Serotonin im Gehirn erhöht. Fluvoxamin hemmt selektiv den Serotonin-Transporter an den Nervenendigungen und hat kaum Wirkung auf andere Rezeptoren. Klinisch bedeutsam ist die starke Hemmung der Leberenzyme CYP1A2 und CYP2C19 sowie die mässige Hemmung von CYP2C9 und CYP3A4 – daher zahlreiche Wechselwirkungen. Die Wirkung auf die Stimmung setzt nach 2–4 Wochen ein.","nebenwirkungen":{"haeufig":["Übelkeit, Erbrechen","Appetitlosigkeit, Bauchschmerzen, Verdauungsbeschwerden","Verstopfung, Durchfall, Mundtrockenheit","Unruhe, Nervosität, Angst, Schlaflosigkeit","Schläfrigkeit, Schwindel, Kopfschmerzen","Zittern (Tremor)","Herzklopfen, Herzrasen","Vermehrtes Schwitzen, Schwäche"],"gelegentlich":["Verwirrtheit, Halluzinationen, Aggressivität","Gangunsicherheit (Ataxie), Bewegungsstörungen","Blutdruckabfall beim Aufstehen","Hautausschlag, Juckreiz, Angioödem","Gelenk- und Muskelschmerzen","Ejakulationsstörungen"],"selten":["Manie","Krampfanfälle","Leberfunktionsstörungen","Lichtempfindlichkeit der Haut","Milchfluss (Galaktorrhö)"],"unbekannt":["Serotoninsyndrom","Hyponatriämie (Natriummangel) durch SIADH","Blutungen (Haut, Schleimhaut, Magen-Darm-Trakt)","Suizidgedanken und suizidales Verhalten","Sitzunruhe (Akathisie)","Absetzsymptome (Schwindel, Missempfindungen, Reizbarkeit)","Anhaltende sexuelle Funktionsstörungen"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Bei Einnahme in der Spätschwangerschaft sind beim Neugeborenen Anpassungsstörungen und ein erhöhtes Risiko für Lungenhochdruck (PPHN) möglich.","stillzeit":"Geht in kleinen Mengen in die Muttermilch über – während der Stillzeit nicht anwenden.","hinweise":["Vor jedem neuen Medikament Apotheke oder Arztpraxis informieren: Fluvoxamin verändert den Abbau vieler Wirkstoffe.","Koffeinkonsum einschränken: Kaffee und Cola wirken stärker und länger (Herzklopfen, Schlaflosigkeit).","Tabletten mit Wasser unzerkaut schlucken; die Wirkung auf die Stimmung setzt nach 2–4 Wochen ein.","Nicht abrupt absetzen, sondern schrittweise nach ärztlicher Anweisung."],"darreichung":["Filmtabletten"]},"folinsaeure":{"wirkmechanismus":"Liefert den Zellen eine bereits aktive Form der Folsäure, die sie für die Bildung von Erbsubstanz brauchen. Calciumfolinat ist ein Derivat der Tetrahydrofolsäure und benötigt – anders als Folsäure – keine Aktivierung durch die Dihydrofolat-Reduktase. Es umgeht daher die Blockade dieses Enzyms durch Methotrexat und schützt gesunde Zellen in Knochenmark und Schleimhäuten. Zusammen mit Fluorouracil stabilisiert es dessen Bindung an die Thymidylat-Synthase und verstärkt so die Hemmung der DNA-Synthese im Tumor.","nebenwirkungen":{"sehrHaeufig":["Mit Fluorouracil: Knochenmarkschädigung (Blutbildveränderungen, auch lebensbedrohlich)","Mit Fluorouracil: Mukositis (Entzündung der Mundschleimhaut)","Mit Fluorouracil: Durchfall, Übelkeit, Erbrechen"],"haeufig":["Mit Fluorouracil: Hand-Fuss-Syndrom (Rötung und Schmerzen an Handflächen und Fusssohlen)"],"gelegentlich":["Fieber nach der Injektion"],"selten":["Schlaflosigkeit, Unruhe, Depression nach hohen Dosen","Magen-Darm-Beschwerden nach hohen Dosen","Häufigere Anfälle bei Epilepsie"],"sehrSelten":["Allergische Reaktionen bis zur Anaphylaxie, Nesselsucht"],"unbekannt":["Mit Fluorouracil: erhöhter Ammoniakspiegel im Blut (Hyperammonämie)"]},"schwangerschaft":"Folinsäure selbst darf bei klarer Notwendigkeit angewendet werden. Methotrexat und Fluorouracil, mit denen sie kombiniert wird, dürfen in der Schwangerschaft jedoch in der Regel nicht angewendet werden.","stillzeit":"Folinsäure ist für den Säugling an sich unbedenklich; wegen der gleichzeitigen Behandlung mit Methotrexat oder Fluorouracil muss jedoch meist abgestillt werden.","hinweise":["Nach hoch dosiertem Methotrexat genau nach dem vorgegebenen Zeitplan anwenden; Methotrexat-Spiegel und Nierenwerte werden dabei kontrolliert.","Unter der Kombination mit Fluorouracil Durchfall, Fieber oder einen entzündeten Mund sofort melden (Gefahr von Austrocknung und Infektion).","Folinsäure ist nicht dasselbe wie Folsäure – Folsäure kann die Wirkung von Methotrexat nicht aufheben."],"darreichung":["Injektions- und Infusionslösung"]},"follitropin-alfa":{"wirkmechanismus":"Regt die Eierstöcke an, Eibläschen (Follikel) heranreifen zu lassen. Follitropin alfa ist gentechnisch hergestelltes menschliches follikelstimulierendes Hormon (FSH); es bindet an FSH-Rezeptoren der Granulosazellen und fördert Wachstum und Reifung der Follikel sowie die Östrogenbildung. Den Eisprung löst anschliessend eine hCG-Injektion aus. Beim Mann stimuliert FSH zusammen mit hCG die Spermienbildung in den Sertoli-Zellen des Hodens.","nebenwirkungen":{"sehrHaeufig":["Eierstockzysten","Kopfschmerzen","Reaktionen an der Einstichstelle (Schmerzen, Rötung, Bluterguss, Schwellung)"],"haeufig":["Bauchschmerzen, Blähbauch, Bauchbeschwerden","Übelkeit, Erbrechen, Durchfall","Leichtes bis mittelschweres ovarielles Überstimulationssyndrom (OHSS)","Männer: Akne, Brustvergrösserung (Gynäkomastie), Krampfader am Hoden (Varikozele), Gewichtszunahme"],"gelegentlich":["Schweres ovarielles Überstimulationssyndrom"],"selten":["Komplikationen eines schweren OHSS, z. B. Stieldrehung des Eierstocks"],"sehrSelten":["Überempfindlichkeitsreaktionen bis Anaphylaxie und Schock","Thromboembolie (meist bei schwerem OHSS)","Verschlechterung eines Asthmas"]},"schwangerschaft":"Nicht angezeigt in der Schwangerschaft.","stillzeit":"Nicht angezeigt in der Stillzeit.","hinweise":["Injektion unter die Haut nach Anleitung, möglichst täglich zur gleichen Zeit.","Regelmässige Ultraschall- und Hormonkontrollen sind nötig, um eine Überstimulation zu vermeiden.","Bei starken Bauchschmerzen, Blähbauch, Übelkeit, Atemnot oder deutlich weniger Urin sofort ärztliche Hilfe holen."],"darreichung":["Injektionslösung im Fertigpen","Pulver und Lösungsmittel zur Herstellung einer Injektionslösung"]},"follitropin-alfa-lutropin-alfa":{"wirkmechanismus":"Ersetzt die beiden Hormone der Hirnanhangsdrüse, die die Eierstöcke für die Reifung der Eibläschen (Follikel) brauchen. Follitropin alfa (FSH) fördert über FSH-Rezeptoren der Granulosazellen Wachstum und Reifung der Follikel; Lutropin alfa (LH) regt in den Thekazellen die Bildung von Androgenen an, die unter FSH-Einfluss zu Östradiol umgewandelt werden. Den Eisprung löst anschliessend eine hCG-Injektion aus.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Eierstockzysten","Reaktionen an der Einstichstelle (Schmerzen, Rötung, Bluterguss, Schwellung)"],"haeufig":["Bauchschmerzen, Blähbauch, Bauchbeschwerden","Übelkeit, Erbrechen, Durchfall","Brust- und Beckenschmerzen","Leichtes bis mittelschweres ovarielles Überstimulationssyndrom (OHSS)"],"gelegentlich":["Schweres ovarielles Überstimulationssyndrom"],"selten":["Komplikationen eines schweren OHSS, z. B. Stieldrehung des Eierstocks"],"sehrSelten":["Überempfindlichkeitsreaktionen bis Anaphylaxie und Schock","Thromboembolie (meist bei schwerem OHSS)","Verschlechterung eines Asthmas"]},"schwangerschaft":"Nicht angezeigt in der Schwangerschaft.","stillzeit":"Nicht angezeigt in der Stillzeit.","hinweise":["Injektion unter die Haut nach Anleitung, möglichst täglich zur gleichen Zeit.","Regelmässige Ultraschall- und Hormonkontrollen sind nötig, um eine Überstimulation zu vermeiden.","Bei starken Bauchschmerzen, Blähbauch, Übelkeit, Atemnot oder deutlich weniger Urin sofort ärztliche Hilfe holen."],"darreichung":["Injektionslösung im Fertigpen","Pulver und Lösungsmittel zur Herstellung einer Injektionslösung"]},"follitropin-beta":{"wirkmechanismus":"Regt die Eierstöcke an, Eibläschen (Follikel) heranreifen zu lassen. Follitropin beta ist gentechnisch hergestelltes menschliches follikelstimulierendes Hormon (FSH); es bindet an FSH-Rezeptoren der Granulosazellen und fördert Wachstum und Reifung der Follikel sowie die Östrogenbildung. Den Eisprung löst anschliessend eine hCG-Injektion aus. Beim Mann stimuliert FSH zusammen mit hCG die Spermienbildung im Hoden.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Blähbauch, Bauchschmerzen","Beckenschmerzen","Ovarielles Überstimulationssyndrom (OHSS)","Reaktionen an der Einstichstelle (Bluterguss, Schmerzen, Rötung, Schwellung, Juckreiz)","Männer: Akne, Brustvergrösserung (Gynäkomastie), Nebenhodenzyste, Hautausschlag"],"gelegentlich":["Allgemeine Überempfindlichkeitsreaktionen (Rötung, Nesselsucht, Ausschlag, Juckreiz)","Übelkeit, Verstopfung, Durchfall, Bauchbeschwerden","Brustbeschwerden, Zwischenblutungen","Eierstockzysten, Vergrösserung von Eierstöcken oder Gebärmutter","Stieldrehung eines Eierstocks (Ovarialtorsion)"],"selten":["Thromboembolie"]},"schwangerschaft":"Nicht angezeigt in der Schwangerschaft.","stillzeit":"Nicht angezeigt in der Stillzeit.","hinweise":["Injektion unter die Haut nach Anleitung, möglichst täglich zur gleichen Zeit.","Regelmässige Ultraschall- und Hormonkontrollen sind nötig, um eine Überstimulation zu vermeiden.","Bei starken Bauchschmerzen, Blähbauch, Übelkeit, Atemnot oder deutlich weniger Urin sofort ärztliche Hilfe holen."],"darreichung":["Injektionslösung (Patrone für Pen)"]},"follitropin-delta":{"wirkmechanismus":"Regt die Eierstöcke an, mehrere Eibläschen (Follikel) heranreifen zu lassen. Follitropin delta ist menschliches follikelstimulierendes Hormon (FSH), das in einer menschlichen Zelllinie hergestellt wird. Es bindet an FSH-Rezeptoren der Granulosazellen und fördert Wachstum und Reifung der Follikel. Die Tagesdosis wird aus dem Anti-Müller-Hormon (AMH) im Blut und dem Körpergewicht berechnet, um eine Über- oder Unterstimulation zu vermeiden.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Beckenschmerzen und -beschwerden, Schmerzen im Bereich der Eierstöcke","Übelkeit","Müdigkeit","Ovarielles Überstimulationssyndrom (OHSS)"],"gelegentlich":["Stimmungsschwankungen","Schläfrigkeit, Schwindel","Durchfall, Erbrechen, Verstopfung, Bauchbeschwerden","Vaginale Blutungen","Brustbeschwerden (Schmerzen, Spannen)"],"unbekannt":["Überempfindlichkeitsreaktionen","Thromboembolie","Stieldrehung eines Eierstocks (Ovarialtorsion)"]},"schwangerschaft":"Nicht angezeigt in der Schwangerschaft.","stillzeit":"Nicht angezeigt in der Stillzeit.","hinweise":["Vor dem ersten Zyklus wird der AMH-Wert im Blut bestimmt; die Dosis gilt für den ganzen Zyklus.","Regelmässige Ultraschall- und Hormonkontrollen sind nötig, um eine Überstimulation zu vermeiden.","Bei starken Bauchschmerzen, Blähbauch, Übelkeit, Atemnot oder deutlich weniger Urin sofort ärztliche Hilfe holen."],"darreichung":["Injektionslösung im Fertigpen"]},"folsaeure":{"wirkmechanismus":"Ersetzt Folsäure, die für die Zellteilung und Blutbildung nötig ist. Folsäure wird im Körper über das Enzym Dihydrofolat-Reduktase zur aktiven Tetrahydrofolsäure umgewandelt. Diese überträgt Kohlenstoff-Bausteine für die Herstellung von Purinen und Thymidin, also für die DNA-Synthese – besonders wichtig in sich rasch teilenden Geweben wie Knochenmark und dem sich entwickelnden Nervensystem des Embryos. Zusammen mit Vitamin B12 wird zudem Homocystein zu Methionin umgebaut.","nebenwirkungen":{"selten":["Magen-Darm-Beschwerden wie Übelkeit, Blähungen (bei hohen Dosen)","Schlafstörungen, Unruhe, depressive Verstimmung (bei hohen Dosen)"],"sehrSelten":["Überempfindlichkeitsreaktionen (Hautrötung, Juckreiz)","Bronchospasmus (Verkrampfung der Atemwege)","Anaphylaktischer Schock (schwere allergische Reaktion)"]},"schwangerschaft":"Erlaubt und empfohlen: ab mindestens 4 Wochen vor der Empfängnis bis Ende des 1. Schwangerschaftsdrittels zur Vorbeugung von Neuralrohrdefekten; bei erhöhtem Risiko höher dosiert nach ärztlicher Verordnung.","stillzeit":"Erlaubt; Folsäure geht in die Muttermilch über, der Bedarf ist in der Stillzeit erhöht.","hinweise":["Bei Kinderwunsch rechtzeitig beginnen: das Neuralrohr schliesst sich bereits in den ersten 4 Wochen der Schwangerschaft.","Hoch dosierte Folsäure (5 mg) nur auf ärztliche Verordnung; vorher einen Vitamin-B12-Mangel ausschliessen lassen.","Während einer Chemotherapie keine folsäurehaltigen Präparate ohne Rücksprache einnehmen."],"darreichung":["Tabletten","Kombinationspräparate mit Eisen oder Multivitaminen"]},"fondaparinux":{"wirkmechanismus":"Hemmt die Blutgerinnung und verhindert so Blutgerinnsel. Fondaparinux ist ein vollsynthetisches Pentasaccharid, das genau der Bindungsstelle des Heparins für Antithrombin entspricht. Es bindet selektiv an Antithrombin und verstärkt dessen Hemmung des Gerinnungsfaktors Xa etwa 300-fach; Thrombin selbst wird nicht gehemmt. Weil es nicht mit dem Plättchenfaktor 4 reagiert, ist eine heparininduzierte Thrombozytopenie praktisch nicht zu erwarten. Fondaparinux wird unverändert über die Nieren ausgeschieden und hat eine lange Halbwertszeit (etwa 17–21 Stunden), sodass eine Spritze pro Tag genügt.","nebenwirkungen":{"haeufig":["Blutungen (nach Operationen, Blutergüsse, Nasenbluten, Magen-Darm-, Harnwegs- und Scheidenblutungen)","Anämie (Blutarmut)"],"gelegentlich":["Thrombozytopenie oder Thrombozytose (veränderte Plättchenzahl), Purpura (punktförmige Hautblutungen)","Übelkeit, Erbrechen","Erhöhte Leberwerte, Leberfunktionsstörung","Hautausschlag, Juckreiz","Wassereinlagerungen, Fieber, Wundsekret"],"selten":["Hirnblutung und Blutungen im hinteren Bauchraum (retroperitoneal)","Allergische Reaktionen","Hypokaliämie (Kaliummangel)","Schwindel, Kopfschmerzen, Benommenheit, Angst, Verwirrtheit","Blutdruckabfall, Atemnot, Husten","Bauchschmerzen, Verdauungsbeschwerden, Verstopfung, Durchfall","Reaktionen an der Einstichstelle"],"sehrSelten":["Angioödem, anaphylaktische oder anaphylaktoide Reaktionen"]},"schwangerschaft":"Keine ausreichenden Erfahrungen beim Menschen; nur anwenden, wenn eindeutig erforderlich.","stillzeit":"Im Tierversuch Übergang in die Milch; Stillen während der Behandlung wird nicht empfohlen.","hinweise":["Unter die Haut spritzen (Bauch, abwechselnd links und rechts), nie in den Muskel; die Luftblase in der Fertigspritze nicht entfernen.","Vor Operationen, Zahnbehandlungen und Spinal- oder Periduralanästhesie die Behandlung angeben.","Nierenfunktion kontrollieren lassen, besonders bei älteren Menschen.","Bei Blutungszeichen (schwarzer Stuhl, Blut im Urin, ungewöhnliche Blutergüsse) sofort ärztlichen Rat holen."],"darreichung":["Injektionslösung in Fertigspritzen"]},"formoterol":{"wirkmechanismus":"Erweitert die Bronchien innert 1–3 Minuten und hält sie etwa 12 Stunden offen. Formoterol stimuliert selektiv Beta-2-Rezeptoren der Bronchialmuskulatur; über einen Anstieg von cAMP erschlafft die glatte Muskulatur. Dank des raschen Wirkungseintritts wird es in Kombination mit Budesonid oder Beclometason auch als Bedarfsmedikament eingesetzt. Gegen die Entzündung der Atemwege wirkt es nicht.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Zittern (Tremor)","Herzklopfen"],"gelegentlich":["Unruhe, Nervosität, Schlafstörungen","Schwindel","Beschleunigter Puls (Tachykardie)","Muskelkrämpfe"],"selten":["Überempfindlichkeitsreaktionen (Ausschlag, Nesselsucht, Juckreiz)","Hypokaliämie (Kaliummangel)","Herzrhythmusstörungen (Vorhofflimmern, supraventrikuläre Tachykardie, Extrasystolen)","Bronchospasmus, auch paradox nach der Inhalation"],"sehrSelten":["Hyperglykämie (erhöhter Blutzucker)","Geschmacksstörungen","Angina pectoris, QT-Verlängerung","Blutdruckschwankungen"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; ein gut kontrolliertes Asthma ist für Mutter und Kind wichtig.","stillzeit":"Nur nach ärztlicher Abwägung; ob Formoterol in die Muttermilch übergeht, ist nicht bekannt.","hinweise":["Bei Asthma immer zusammen mit einem inhalativen Kortison anwenden, am einfachsten als Kombinationspräparat.","Inhalationstechnik in der Apotheke oder Praxis zeigen lassen; Kapseln nur in den Inhalator einlegen, nie schlucken.","Bei zunehmendem Bedarf oder nachlassender Wirkung ärztlich abklären lassen."],"darreichung":["Pulverinhalator","Kapseln zur Inhalation"]},"formoterol-beclometason":{"wirkmechanismus":"Verbindet eine entzündungshemmende mit einer rasch einsetzenden, lang anhaltenden bronchienerweiternden Wirkung. Beclometasondipropionat ist ein Prodrug: In der Lunge entsteht daraus das wirksame Beclometason-17-monopropionat, das die Entzündung der Bronchialschleimhaut dämpft. Formoterol stimuliert Beta-2-Rezeptoren und weitet die Bronchien innert Minuten für etwa 12 Stunden. Dank sehr feiner Partikel erreicht der Wirkstoff auch die kleinen Atemwege, weshalb die Kortisondosis tiefer ist als bei herkömmlichen Beclometason-Präparaten.","nebenwirkungen":{"haeufig":["Pilzinfektion in Mund und Rachen (Soor), Rachenentzündung","Kopfschmerzen","Heiserkeit (Dysphonie)","Lungenentzündung (bei COPD)"],"gelegentlich":["Grippe, Nebenhöhlenentzündung, Schnupfen","Zittern, Schwindel, Unruhe","Herzklopfen, beschleunigter Puls, Vorhofflimmern, QT-Verlängerung","Husten, Rachenreizung, Asthmaanfall","Übelkeit, Mundtrockenheit, Geschmacksstörungen","Hypokaliämie, Hyperglykämie","Hautausschlag, Juckreiz, Nesselsucht","Muskelkrämpfe, Muskelschmerzen"],"selten":["Paradoxer Bronchospasmus","Angioödem","Ventrikuläre Extrasystolen, Angina pectoris","Blutdruckanstieg oder -abfall"],"sehrSelten":["Unterdrückung der Nebennierenfunktion, Wachstumsverzögerung bei Kindern, verminderte Knochendichte","Glaukom, Katarakt","Thrombozytopenie (Mangel an Blutplättchen)","Periphere Ödeme (Wassereinlagerungen)"],"unbekannt":["Schlafstörungen, Angst, Depression, Aggressivität, Verhaltensänderungen","Verschwommenes Sehen"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; ein gut kontrolliertes Asthma ist für Mutter und Kind wichtig. Gegen Ende der Schwangerschaft zurückhaltend, da Beta-2-Sympathomimetika die Wehen hemmen können.","stillzeit":"Nur nach ärztlicher Abwägung.","hinweise":["Nach jeder Inhalation den Mund mit Wasser ausspülen und ausspucken – das beugt Soor und Heiserkeit vor.","Regelmässig anwenden, auch ohne Beschwerden; nicht abrupt absetzen.","Inhalationstechnik in der Apotheke oder Praxis zeigen lassen; beim Dosieraerosol kann eine Inhalierhilfe (Spacer) sinnvoll sein."],"darreichung":["Dosieraerosol","Pulverinhalator"]},"formoterol-budesonid":{"wirkmechanismus":"Verbindet eine entzündungshemmende mit einer rasch einsetzenden, lang anhaltenden bronchienerweiternden Wirkung. Budesonid ist ein Glukokortikoid, das die Entzündung der Bronchialschleimhaut und die Überempfindlichkeit der Atemwege dämpft. Formoterol stimuliert Beta-2-Rezeptoren der Bronchialmuskulatur; die Bronchien weiten sich innert 1–3 Minuten für etwa 12 Stunden. Wegen des raschen Wirkungseintritts kann die Kombination bei Asthma gleichzeitig zur Dauer- und Bedarfsbehandlung dienen.","nebenwirkungen":{"haeufig":["Pilzinfektion in Mund und Rachen (Soor)","Lungenentzündung (bei COPD)","Kopfschmerzen","Zittern (Tremor)","Herzklopfen","Leichte Rachenreizung, Husten, Heiserkeit"],"gelegentlich":["Angst, Unruhe, Nervosität, Schlafstörungen","Schwindel","Übelkeit","Beschleunigter Puls (Tachykardie)","Verschwommenes Sehen","Muskelkrämpfe","Blutergüsse"],"selten":["Überempfindlichkeitsreaktionen (Ausschlag, Nesselsucht, Juckreiz, Angioödem, Anaphylaxie)","Hypokaliämie (Kaliummangel)","Herzrhythmusstörungen (Vorhofflimmern, supraventrikuläre Tachykardie, Extrasystolen)","Bronchospasmus (Verkrampfung der Atemwege)"],"sehrSelten":["Cushing-Syndrom, Unterdrückung der Nebennierenfunktion, Wachstumsverzögerung, verminderte Knochendichte","Hyperglykämie (erhöhter Blutzucker)","Depression, Verhaltensänderungen","Katarakt, Glaukom","Angina pectoris, QT-Verlängerung","Geschmacksstörungen","Blutdruckschwankungen"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; ein gut kontrolliertes Asthma ist für Mutter und Kind wichtig. Für inhaliertes Budesonid liegen umfangreiche Erfahrungen ohne Hinweis auf Fehlbildungen vor.","stillzeit":"Budesonid geht in geringen Mengen in die Muttermilch über; ob Formoterol übergeht, ist nicht bekannt. Anwendung nach ärztlicher Abwägung.","hinweise":["Nach jeder Inhalation den Mund mit Wasser ausspülen und ausspucken – das beugt Soor und Heiserkeit vor.","Wer das Präparat auch bei Bedarf anwendet: Wird es an mehreren Tagen deutlich häufiger als gewohnt gebraucht, ärztlich abklären lassen.","Nicht abrupt absetzen; eine Ritonavir- oder Cobicistat-haltige HIV-Therapie ärztlich angeben."],"darreichung":["Pulverinhalator","Dosieraerosol"]},"formoterol-fluticason":{"wirkmechanismus":"Wirkt bei Asthma auf zwei Wegen: Es dämpft die Entzündung der Bronchien und erweitert sie. Fluticasonpropionat ist ein stark wirksames Glukokortikoid, das über den Glukokortikoid-Rezeptor die Bildung von Entzündungsbotenstoffen und die Einwanderung von Entzündungszellen in die Bronchialschleimhaut hemmt. Formoterol stimuliert selektiv die Beta-2-Rezeptoren der Bronchialmuskulatur und entspannt sie; die Wirkung setzt innerhalb weniger Minuten ein und hält etwa 12 Stunden an.","nebenwirkungen":{"gelegentlich":["Mundsoor (Pilzinfektion in Mund und Rachen)","Kopfschmerzen, Schwindel","Zittern (Tremor)","Herzklopfen, Extraschläge des Herzens (ventrikuläre Extrasystolen)","Heiserkeit (Dysphonie), Rachenreizung","Verschlechterung des Asthmas","Schlafstörungen"],"selten":["Hyperglykämie (erhöhter Blutzucker)","Angina pectoris (Brustenge), Herzrasen (Tachykardie)","Bluthochdruck","Atemnot, Husten","Mundtrockenheit, Durchfall, Verdauungsbeschwerden","Hautausschlag, Juckreiz","Muskelkrämpfe, Geschmacksstörungen","Ungewöhnliche Träume, Unruhe"],"unbekannt":["Paradoxer Bronchospasmus (Verkrampfung der Atemwege direkt nach dem Inhalieren)","Hypokaliämie (Kaliummangel)","Systemische Kortisonwirkungen bei hoher Dosis über lange Zeit (Nebennierenunterdrückung, Wachstumsverzögerung, Abnahme der Knochendichte, grauer und grüner Star)","Verschwommensehen","Psychomotorische Überaktivität, Angst, Depression, Aggressivität (v. a. bei Kindern)"]},"schwangerschaft":"Nur anwenden, wenn der Nutzen für die Mutter das mögliche Risiko für das Kind überwiegt; eine gute Asthmakontrolle ist auch für das Ungeborene wichtig. Formoterol kann kurz vor der Geburt die Wehen hemmen.","stillzeit":"Nicht bekannt, ob die Wirkstoffe in die Muttermilch übergehen; Anwendung nur nach ärztlicher Nutzen-Risiko-Abwägung.","hinweise":["Regelmässig wie verordnet anwenden (in der Regel morgens und abends), auch bei Beschwerdefreiheit; für akute Atemnot immer ein separates Notfallspray bereithalten.","Nach jeder Anwendung den Mund mit Wasser ausspülen und ausspucken – beugt Mundsoor und Heiserkeit vor.","Nicht abrupt absetzen; bei Verschlechterung oder häufigerem Gebrauch des Notfallsprays ärztlich melden.","Inhalationstechnik regelmässig in Apotheke oder Praxis überprüfen lassen; bei Koordinationsproblemen eine Inhalierhilfe (Spacer) verwenden."],"darreichung":["Dosieraerosol (Inhalationsspray)"]},"fosaprepitant":{"wirkmechanismus":"Verhindert vor allem das verzögerte Erbrechen in den Tagen nach einer Chemotherapie. Fosaprepitant ist eine Vorstufe (Prodrug), die nach der Infusion rasch zum Wirkstoff Aprepitant umgewandelt wird. Aprepitant blockiert im Gehirn die NK1-Rezeptoren für den Botenstoff Substanz P, der den Brechreflex auslöst, und ergänzt so die Wirkung von 5-HT3-Antagonisten und Dexamethason. Aprepitant hemmt vorübergehend das Abbauenzym CYP3A4 und regt die Enzyme CYP2C9 und CYP3A4 danach leicht an.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Müdigkeit","Schluckauf","Obstipation (Verstopfung)","Dyspepsie (Verdauungsbeschwerden)","Appetitlosigkeit","Erhöhte Leberwerte (ALT)"],"gelegentlich":["Schwindel, Schläfrigkeit","Herzklopfen, Hitzewallungen","Übelkeit, Aufstossen, Bauchschmerzen","Hautausschlag, Akne","Anämie (Blutarmut)"],"selten":["Stevens-Johnson-Syndrom und toxische epidermale Nekrolyse (schwere Hautreaktionen)"],"unbekannt":["Überempfindlichkeitsreaktionen bis Anaphylaxie, auch während der Infusion","Reaktionen an der Infusionsstelle (Rötung, Schmerzen, Verhärtung, Venenentzündung)"]},"schwangerschaft":"Nur begrenzte Daten; nur anwenden, wenn eindeutig notwendig. Hormonelle Verhütung kann bis rund einen Monat nach der Gabe unsicher sein.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Alle Medikamente angeben: Aprepitant beeinflusst den Abbau vieler Arzneimittel über mehrere Tage (u. a. Kortison, Blutverdünner, Antibabypille).","Bei Einnahme von Phenprocoumon oder Acenocoumarol den INR in den zwei Wochen nach der Infusion kontrollieren lassen."],"darreichung":["Pulver zur Herstellung einer Infusionslösung"]},"foscarnet":{"wirkmechanismus":"Blockiert die Vermehrung von Herpesviren direkt an deren Kopierenzym. Foscarnet ahmt Pyrophosphat nach und hemmt die virale DNA-Polymerase an der Pyrophosphat-Bindungsstelle. Anders als Aciclovir oder Ganciclovir muss es nicht durch virale Enzyme aktiviert werden und wirkt deshalb auch gegen viele Viren, die gegen diese Mittel resistent sind. Foscarnet bindet zweiwertige Ionen wie Calcium und Magnesium, was die typischen Elektrolytstörungen erklärt.","nebenwirkungen":{"sehrHaeufig":["Granulozytopenie, Anämie","Hypokaliämie, Hypomagnesiämie, verminderter Appetit","Kopfschmerzen, Schwindel, Kribbeln (Parästhesien)","Übelkeit, Erbrechen, Durchfall","Ausschlag","Nierenfunktionsstörung (Kreatininanstieg)","Fieber, Schüttelfrost, Schwäche"],"haeufig":["Hypokalzämie, Hypo- oder Hyperphosphatämie, Hyponatriämie","Krampfanfälle, Zittern, Muskelzuckungen, Neuropathie","Unruhe, Angst, Verwirrtheit, Depression, Aggression","Herzrasen, Herzklopfen, Blutdruckveränderungen, Venenentzündung","Akutes Nierenversagen, Eiweiss im Urin","Geschwüre und Beschwerden im Genitalbereich","Abnorme Leberfunktion, Pankreatitis","Thrombozytopenie, Leukopenie, Sepsis"],"gelegentlich":["Panzytopenie","Metabolische Azidose","Nesselsucht, Angioödem"],"unbekannt":["QT-Verlängerung, Torsade de pointes, Kammerrhythmusstörungen","Nephrogener Diabetes insipidus, Kristallnephropathie, renale tubuläre Azidose","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, Erythema multiforme","Rhabdomyolyse, Speiseröhrengeschwüre","Hyperkalzämie"]},"schwangerschaft":"Erfahrungen beim Menschen fehlen; nur bei klarer Notwendigkeit anwenden.","stillzeit":"Nicht stillen.","hinweise":["Wird im Spital als Infusion gegeben; vorher und dazu wird reichlich Flüssigkeit verabreicht, um die Nieren zu schützen.","Nierenwerte und Elektrolyte (Calcium, Magnesium, Kalium, Phosphat) werden mehrmals pro Woche kontrolliert.","Kribbeln um den Mund oder in Händen und Füssen sofort melden (Hinweis auf tiefes Calcium).","Nach dem Wasserlassen den Genitalbereich gut waschen, um Reizungen und Geschwüren vorzubeugen."],"darreichung":["Infusionslösung"]},"fosfomycin":{"wirkmechanismus":"Hindert Bakterien daran, ihre Zellwand aufzubauen, und tötet sie dadurch ab. Fosfomycin hemmt irreversibel das Enzym MurA (UDP-N-Acetylglucosamin-Enolpyruvyl-Transferase) und blockiert damit den allerersten Schritt der Peptidoglykan-Synthese – früher als Penicilline oder Cephalosporine, weshalb kaum Kreuzresistenzen bestehen. Der Wirkstoff wird unverändert über die Niere ausgeschieden und erreicht nach einer einzigen Dosis für 1–2 Tage hohe Konzentrationen im Urin.","nebenwirkungen":{"haeufig":["Durchfall","Übelkeit","Dyspepsie (Verdauungsbeschwerden)","Bauchschmerzen","Kopfschmerzen","Schwindel","Vulvovaginitis (Scheidenentzündung, z. B. Scheidenpilz)"],"gelegentlich":["Erbrechen","Hautausschlag, Juckreiz, Nesselsucht","Parästhesien (Kribbeln)"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion) bis Schock","Angioödem (Schwellung von Gesicht, Lippen, Rachen)","Antibiotika-assoziierte Kolitis (Clostridioides difficile)"]},"schwangerschaft":"Erfahrungen mit der Einmalgabe zeigen kein erhöhtes Risiko für das Kind; Anwendung nach ärztlicher Abwägung möglich.","stillzeit":"Geht in geringen Mengen in die Muttermilch über. Eine einmalige Dosis ist nach ärztlicher Abwägung vertretbar.","hinweise":["Granulat in einem Glas Wasser auflösen und sofort trinken – auf nüchternen Magen, am besten am Abend vor dem Schlafengehen nach Entleeren der Blase.","Die Beschwerden klingen oft erst nach 2–3 Tagen ab; bei Fieber, Rückenschmerzen oder fehlender Besserung ärztlich abklären lassen.","Nach der Einnahme ausreichend trinken."],"darreichung":["Granulat zur Herstellung einer Trinklösung (Beutel)"]},"fosinopril":{"wirkmechanismus":"Senkt den Blutdruck, indem es die Bildung des gefässverengenden Hormons Angiotensin II hemmt. Fosinopril ist ein Prodrug, das in Darmwand und Leber zum wirksamen Fosinoprilat umgewandelt wird; dieses hemmt das Angiotensin-Converting-Enzym (ACE), sodass Angiotensin II und Aldosteron sinken und sich die Gefässe erweitern. Weil ACE auch Bradykinin abbaut, steigt dieses an – das erklärt Reizhusten und Angioödeme. Fosinoprilat wird sowohl über die Niere als auch über die Leber ausgeschieden und reichert sich daher bei eingeschränkter Nierenfunktion weniger an.","nebenwirkungen":{"haeufig":["Schwindel, Kopfschmerzen","Husten","Tachykardie (Herzrasen)","Hypotonie, auch beim Aufstehen","Übelkeit, Erbrechen, Durchfall","Hautausschlag","Muskel- und Knochenschmerzen","Müdigkeit, Schwäche, Brustschmerzen"],"gelegentlich":["Angioödem (Schwellung von Gesicht, Lippen, Zunge oder Rachen)","Herzklopfen, Angina pectoris (Brustenge)","Synkope (Ohnmacht)","Kribbeln, Schläfrigkeit, Schlafstörungen","Juckreiz, Nesselsucht","Nierenfunktionsstörung","Sexuelle Funktionsstörungen"],"sehrSelten":["Agranulozytose","Intestinales Angioödem (Darmschwellung mit Bauchschmerzen)"],"unbekannt":["Hyperkaliämie (erhöhtes Kalium)","Hepatitis, Gelbsucht durch Gallenstau","Pankreatitis","Akutes Nierenversagen","Schwere Hautreaktionen"]},"schwangerschaft":"Im 1. Drittel nicht empfohlen, im 2. und 3. Drittel kontraindiziert (Schädigung der kindlichen Nieren, Fruchtwassermangel, Verknöcherungsstörungen des Schädels). Bei Kinderwunsch oder Schwangerschaft auf ein anderes Mittel umstellen.","stillzeit":"Geht in die Muttermilch über; nicht empfohlen – besser untersuchte Alternativen wählen.","hinweise":["Bei Schwellungen von Gesicht, Lippen, Zunge oder Rachen oder bei Atemnot sofort den Notfall aufsuchen (Angioödem).","Trockener Reizhusten ist eine typische Nebenwirkung – ärztlich melden, nicht selbst absetzen.","Kalium und Nierenwerte regelmässig kontrollieren; kaliumhaltige Salzersatzmittel meiden.","Antazida (Säurebinder) mindestens 2 Stunden versetzt einnehmen."],"darreichung":["Tabletten"]},"foslevodopa-foscarbidopa":{"wirkmechanismus":"Ersetzt den bei Parkinson fehlenden Botenstoff Dopamin im Gehirn. Foslevodopa und Foscarbidopa sind gut wasserlösliche Phosphat-Prodrugs, die nach der Infusion unter die Haut rasch zu Levodopa und Carbidopa umgewandelt werden. Levodopa gelangt ins Gehirn und wird dort zu Dopamin; Carbidopa hemmt diese Umwandlung ausserhalb des Gehirns und vermindert so Nebenwirkungen wie Übelkeit. Die Dauerinfusion ergibt über 24 Stunden gleichmässige Levodopa-Spiegel.","nebenwirkungen":{"sehrHaeufig":["Reaktionen an der Infusionsstelle (Rötung, Schwellung, Knoten, Schmerzen, Blutergüsse)","Infektionen an der Infusionsstelle (Zellulitis, Abszess)"],"haeufig":["Halluzinationen, Angst, Depression, Schlaflosigkeit, Verwirrtheit","Dyskinesien (unwillkürliche Überbewegungen)","Schwindel, Kopfschmerzen, Schläfrigkeit","Orthostatische Hypotonie (Blutdruckabfall beim Aufstehen)","Übelkeit, Verstopfung, Erbrechen, Mundtrockenheit","Stürze","Periphere Ödeme (Beinschwellungen)","Gewichtsabnahme"],"unbekannt":["Impulskontrollstörungen (z. B. Spielsucht, Kaufsucht)","Plötzliches Einschlafen","Psychotische Störungen, Dopamin-Dysregulationssyndrom","Malignes neuroleptisches Syndrom bei abruptem Absetzen"]},"schwangerschaft":"Nicht empfohlen; Frauen im gebärfähigen Alter sollen zuverlässig verhüten.","stillzeit":"Levodopa geht in die Muttermilch über und kann die Milchbildung hemmen; während der Behandlung nicht stillen.","hinweise":["Die Infusionsstelle regelmässig wechseln und auf Rötung, Schmerzen oder Eiter achten.","Die Pumpe nicht eigenmächtig für längere Zeit unterbrechen und nicht abrupt absetzen (starke Bewegungsblockade, malignes neuroleptisches Syndrom).","Plötzliches Einschlafen möglich – dann nicht Auto fahren und keine Maschinen bedienen."],"darreichung":["Infusionslösung zur subkutanen Anwendung (Pumpe)"]},"fostemsavir":{"wirkmechanismus":"Hindert das HI-Virus daran, an menschliche Abwehrzellen anzudocken. Fostemsavir ist eine Vorstufe (Prodrug), die im Darm zu Temsavir umgewandelt wird. Temsavir bindet direkt an das Virus-Hüllprotein gp120 nahe der CD4-Bindungsstelle und hält es in einer Form fest, in der es nicht an den CD4-Rezeptor der Zielzellen binden kann. Dadurch werden Anheftung und Eintritt des Virus verhindert, unabhängig davon, welchen Korezeptor das Virus nutzt.","nebenwirkungen":{"sehrHaeufig":["Durchfall","Übelkeit","Kopfschmerzen"],"haeufig":["Erbrechen, Bauchschmerzen, Verdauungsbeschwerden, Blähungen","Schwindel, Schläfrigkeit, Geschmacksstörungen","Schlafstörungen","Hautausschlag, Juckreiz","Muskelschmerzen, erhöhte CK (Muskelenzym)","Müdigkeit","Verlängerung der QT-Zeit im EKG","Erhöhte Leberwerte, erhöhtes Kreatinin"]},"schwangerschaft":"Nur wenige Daten beim Menschen. Anwendung nur, wenn der Nutzen das Risiko überwiegt; die HIV-Therapie in der Schwangerschaft legt eine spezialisierte Fachperson fest.","stillzeit":"Frauen mit HIV wird in der Regel vom Stillen abgeraten; das Vorgehen mit der behandelnden Fachperson besprechen.","hinweise":["Retardtabletten ganz schlucken, nicht teilen, zerkauen oder zerdrücken; Einnahme mit oder ohne Mahlzeit.","Bei der Pille höchstens 30 µg Ethinylestradiol pro Tag – Verhütung ärztlich besprechen.","Vor der Einnahme neuer Medikamente, auch pflanzlicher wie Johanniskraut, ärztlich oder in der Apotheke nachfragen."],"darreichung":["Retardtabletten"]},"fotemustin":{"wirkmechanismus":"Hemmt die Vermehrung von Krebszellen, indem es ihr Erbgut schädigt. Fotemustin ist ein Nitrosoharnstoff mit einer Phosphonoalanin-Gruppe, die die Aufnahme in die Zellen und das Überwinden der Blut-Hirn-Schranke erleichtert. Es alkyliert und vernetzt die DNA und carbamoyliert Eiweisse. Die Knochenmarkhemmung tritt verzögert auf (Tiefpunkt nach 4–6 Wochen).","nebenwirkungen":{"sehrHaeufig":["Verzögerte Thrombozytopenie und Leukopenie (Tiefpunkt nach 4–6 Wochen)","Anämie (Blutarmut)","Übelkeit und Erbrechen (innert 2 Stunden nach der Infusion)","Vorübergehender Anstieg der Leberwerte"],"haeufig":["Fieber","Venenentzündung an der Infusionsstelle (v. a. bei Paravasat)","Durchfall, Bauchschmerzen","Vorübergehender Anstieg des Harnstoffs im Blut"],"gelegentlich":["Juckreiz","Vorübergehende neurologische Störungen (Bewusstseinsstörungen, Kribbeln, Geschmacksstörungen)"],"unbekannt":["Akutes Atemnotsyndrom bei Kombination mit Dacarbazin","Zweitkrebs (Myelodysplasie, akute Leukämie)"]},"schwangerschaft":"Kontraindiziert. Frauen und Männer müssen während der Behandlung sicher verhüten.","stillzeit":"Kontraindiziert.","hinweise":["Infusion im Spital, vor Licht geschützt; Austreten der Lösung neben die Vene vermeiden.","Blutbild vor jeder Gabe; wegen der verzögerten Knochenmarkhemmung werden lange Behandlungspausen eingehalten.","Bei Fieber, Blutungszeichen oder Atemnot sofort ärztliche Hilfe holen.","Keine Lebendimpfungen während der Behandlung."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Infusionslösung"]},"fremanezumab":{"wirkmechanismus":"Beugt Migräneanfällen vor, indem es einen Botenstoff abfängt, der bei der Migräne Gefässerweiterung und Schmerz vermittelt. Fremanezumab ist ein humanisierter IgG2-Antikörper, der den Botenstoff CGRP (Calcitonin Gene-Related Peptide) selbst bindet und so dessen Andocken an den Rezeptor verhindert. Als Eiweiss wird es nicht über Leberenzyme (CYP) abgebaut; dank langer Halbwertszeit genügt eine Injektion pro Monat oder eine dreifache Dosis alle 3 Monate.","nebenwirkungen":{"sehrHaeufig":["Schmerzen an der Injektionsstelle","Verhärtung an der Injektionsstelle","Rötung an der Injektionsstelle"],"haeufig":["Juckreiz an der Injektionsstelle"],"gelegentlich":["Ausschlag an der Injektionsstelle","Überempfindlichkeitsreaktionen (Ausschlag, Juckreiz, Nesselsucht, Schwellungen)"],"selten":["Anaphylaxie (schwere allergische Reaktion)"]},"schwangerschaft":"Nur begrenzte Erfahrungen; aus Vorsicht während der Schwangerschaft nicht anwenden.","stillzeit":"Unbekannt, ob Fremanezumab in die Muttermilch übergeht; besonders in den ersten Tagen nach der Geburt möglich – nur nach ärztlicher Abwägung.","hinweise":["Fertigspritze oder Fertigpen vor der Injektion etwa 30 Minuten bei Raumtemperatur liegen lassen; im Kühlschrank lagern, nicht einfrieren.","Die Wirkung wird nach etwa 3 Monaten ärztlich beurteilt; Akutmittel gegen Migräneanfälle weiter wie verordnet verwenden.","Bei Atemnot, Schwellungen im Gesicht oder starkem Ausschlag sofort ärztliche Hilfe holen."],"darreichung":["Injektionslösung in Fertigspritze oder Fertigpen (subkutan)"]},"fruquintinib":{"wirkmechanismus":"Hungert den Tumor aus, indem es die Bildung neuer Blutgefässe hemmt. Fruquintinib blockiert hochselektiv die Tyrosinkinasen der VEGF-Rezeptoren 1, 2 und 3. Dadurch werden Gefässneubildung (Angiogenese) und Tumorwachstum gebremst.","nebenwirkungen":{"sehrHaeufig":["Bluthochdruck","Hand-Fuss-Syndrom (schmerzhafte Rötung von Händen und Füssen)","Proteinurie (Eiweiss im Urin)","Dysphonie (Heiserkeit)","Durchfall, Stomatitis, Bauchschmerzen","Müdigkeit, Schwäche, Appetitlosigkeit","Hypothyreose (Schilddrüsenunterfunktion)","Thrombozytopenie; erhöhte Leberwerte und erhöhtes Bilirubin"],"haeufig":["Blutungen (z. B. Magen-Darm-Blutungen, Nasenbluten)","Infektionen (z. B. Lungenentzündung, obere Atemwege)","Gelenk- und Muskelschmerzen","Gewichtsabnahme","Erhöhte Lipase und Amylase"],"gelegentlich":["Magen-Darm-Perforation (Durchbruch)","Pankreatitis (Bauchspeicheldrüsenentzündung)"],"unbekannt":["Arterielle Thromboembolien (z. B. Herzinfarkt, Schlaganfall)","Posteriores reversibles Enzephalopathie-Syndrom (PRES, Hirnschwellung mit Kopfschmerzen, Sehstörungen, Krampfanfällen)"]},"schwangerschaft":"Nicht anwenden (im Tierversuch fruchtschädigend). Frauen und Männer müssen während und mindestens 2 Wochen nach der Behandlung zuverlässig verhüten.","stillzeit":"Während der Behandlung und bis 2 Wochen nach der letzten Dosis nicht stillen.","hinweise":["Einnahme im Zyklus: 21 Tage täglich, danach 7 Tage Pause; mit oder ohne Essen, Kapseln ganz schlucken.","Blutdruck regelmässig messen; starke Bauchschmerzen, Blutungen oder starke Kopfschmerzen sofort melden.","Vor Operationen die Behandlung angeben (Wundheilung).","Regelmässige Kontrollen: Blutdruck, Urin auf Eiweiss, Leber- und Schilddrüsenwerte."],"darreichung":["Hartkapseln"]},"fsme-impfstoff":{"wirkmechanismus":"Regt das Immunsystem an, eigene Abwehrstoffe gegen das FSME-Virus zu bilden. Der Impfstoff enthält mit Formaldehyd abgetötete FSME-Viren (FSME-Immun: Stamm Neudörfl, Encepur: Stamm K23), die an Aluminiumhydroxid gebunden sind und so eine stärkere Immunantwort auslösen. Es entstehen neutralisierende Antikörper, die das Virus nach einem Zeckenstich unschädlich machen. Ein langdauernder Schutz erfordert eine Grundimmunisierung mit 3 Dosen und Auffrischimpfungen.","nebenwirkungen":{"sehrHaeufig":["Schmerzen an der Einstichstelle","Kopfschmerzen","Muskelschmerzen","Unwohlsein, Müdigkeit"],"haeufig":["Übelkeit","Gelenkschmerzen","Fieber (vor allem bei Kleinkindern nach der ersten Dosis)","Rötung und Schwellung an der Einstichstelle","Grippeähnliche Beschwerden"],"gelegentlich":["Lymphknotenschwellung","Erbrechen"],"selten":["Überempfindlichkeitsreaktionen","Schwindel","Durchfall, Bauchschmerzen"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Krampfanfälle, auch Fieberkrämpfe","Nervenentzündungen wie Guillain-Barré-Syndrom","Hirnhautreizung (Meningismus)","Verschlechterung von Autoimmunerkrankungen (z. B. multiple Sklerose)"]},"schwangerschaft":"Keine ausreichenden Daten. Impfung nur bei dringendem Ansteckungsrisiko nach ärztlicher Nutzen-Risiko-Abwägung.","stillzeit":"Nicht bekannt, ob Impfstoffbestandteile in die Muttermilch übergehen. Impfung bei Ansteckungsrisiko nach ärztlicher Abwägung möglich.","hinweise":["Grundimmunisierung mit 3 Dosen; in der Schweiz wird eine Auffrischimpfung alle 10 Jahre empfohlen.","Am besten in der kalten Jahreszeit beginnen, damit der Schutz zu Beginn der Zeckensaison besteht; ein Schnellschema ist möglich.","Die Impfung schützt nicht vor Borreliose – Zeckenschutz und Absuchen nach Zecken bleiben wichtig."],"darreichung":["Injektionssuspension in Fertigspritze"]},"fulvestrant":{"wirkmechanismus":"Blockiert den Östrogenrezeptor in Brustkrebszellen und sorgt dafür, dass er abgebaut wird. Fulvestrant bindet kompetitiv und mit hoher Affinität an den Östrogenrezeptor, verhindert dessen Aktivierung und beschleunigt seinen Abbau (Downregulation). Anders als Tamoxifen hat es keine östrogenartige Teilwirkung.","nebenwirkungen":{"sehrHaeufig":["Reaktionen an der Injektionsstelle (Schmerzen, Entzündung)","Schwäche, Müdigkeit","Übelkeit","Erhöhte Leberwerte","Hitzewallungen","Gelenk- und Muskelschmerzen","Hautausschlag"],"haeufig":["Kopfschmerzen","Venöse Thromboembolien","Harnwegsinfektionen","Erbrechen, Durchfall, Appetitlosigkeit","Erhöhtes Bilirubin","Rückenschmerzen","Ischiasschmerzen, Nervenschmerzen an der Injektionsstelle","Überempfindlichkeitsreaktionen, Scheidenblutungen"],"gelegentlich":["Leberversagen, Hepatitis","Blutungen und Blutergüsse an der Injektionsstelle","Scheidenpilz, Ausfluss","Anaphylaxie (schwere allergische Reaktion)"]},"schwangerschaft":"Kontraindiziert. Frauen im gebärfähigen Alter sollen während und bis 2 Jahre nach der letzten Dosis sicher verhüten.","stillzeit":"Kontraindiziert.","hinweise":["Wird als zwei Spritzen in die Gesässmuskulatur gegeben, anfangs zusätzlich nach 2 Wochen, dann monatlich.","Fulvestrant kann bestimmte Östradiol-Labortests verfälschen – bei Blutentnahmen angeben.","Schmerzen, die vom Gesäss ins Bein ausstrahlen, melden."],"darreichung":["Injektionslösung in Fertigspritze (in den Muskel)"]},"furosemid":{"wirkmechanismus":"Bewirkt eine rasche und kräftige Ausscheidung von Salz und Wasser über die Niere. Furosemid hemmt den Natrium-Kalium-2-Chlorid-Cotransporter (NKCC2) im aufsteigenden Teil der Henle-Schleife, wo ein grosser Teil des Natriums zurückgewonnen wird; dadurch steigt die Ausscheidung von Natrium, Chlorid und Wasser, aber auch von Kalium, Calcium und Magnesium deutlich an. Nach Einnahme setzt die Wirkung innerhalb einer Stunde ein und hält 4–6 Stunden an, nach intravenöser Gabe beginnt sie innerhalb weniger Minuten. Bei akuter Herzinsuffizienz entlastet es das Herz zusätzlich durch eine Erweiterung der Venen. Die Wirkung bleibt auch bei eingeschränkter Nierenfunktion erhalten.","nebenwirkungen":{"sehrHaeufig":["Elektrolytstörungen","Flüssigkeitsmangel (Dehydratation, Hypovolämie), besonders bei älteren Menschen","Anstieg von Kreatinin und Triglyceriden im Blut"],"haeufig":["Hypokaliämie, Hyponatriämie, Hypochlorämie (Kalium-, Natrium-, Chloridmangel)","Bluteindickung (Hämokonzentration)","Erhöhtes Cholesterin, erhöhte Harnsäure, Gichtanfälle","Hepatische Enzephalopathie bei Leberinsuffizienz","Vermehrte Harnmenge"],"gelegentlich":["Thrombozytopenie (Mangel an Blutplättchen)","Hörstörungen, meist vorübergehend; Taubheit, teils bleibend","Übelkeit","Juckreiz, Nesselsucht, Hautausschläge, bullöse Hautreaktionen, Photosensibilität","Verschlechterung der Blutzuckereinstellung"],"selten":["Anaphylaktische Reaktionen bis zum Schock","Interstitielle Nephritis (Nierenentzündung)","Vaskulitis (Gefässentzündung)","Eosinophilie, Leukopenie","Erbrechen, Durchfall","Kribbeln (Parästhesien), Fieber"],"sehrSelten":["Agranulozytose, aplastische und hämolytische Anämie","Akute Pankreatitis (Bauchspeicheldrüsenentzündung)","Gallenstau in der Leber, Anstieg der Leberwerte","Tinnitus (Ohrgeräusche)"],"unbekannt":["Hypokalzämie, Hypomagnesiämie, metabolische Alkalose","Schwindel, Ohnmacht, Kopfschmerzen","Thrombosen","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS, AGEP)","Akutes Nierenversagen, Harnverhalt","Nierenverkalkung und offener Ductus arteriosus bei Frühgeborenen","Rhabdomyolyse (Muskelzerfall)"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit und kurzzeitig: Furosemid gelangt zum Kind und kann dessen Elektrolythaushalt sowie die Durchblutung der Plazenta beeinträchtigen; das Wachstum des Kindes überwachen.","stillzeit":"Kontraindiziert: Furosemid geht in die Muttermilch über und kann die Milchbildung hemmen; ist eine Behandlung nötig, abstillen.","hinweise":["Am Morgen bzw. bei zweimaliger Gabe spätestens am frühen Nachmittag einnehmen, um nächtlichen Harndrang zu vermeiden.","Körpergewicht bei Ödemen täglich kontrollieren; bei Durchfall, Erbrechen, starkem Schwitzen oder Schwindel ärztlichen Rat einholen (Austrocknung, Elektrolytverlust).","Kalium, Natrium, Nierenwerte, Blutzucker und Harnsäure regelmässig kontrollieren lassen.","Kann die Fahrtüchtigkeit beeinträchtigen, besonders zu Behandlungsbeginn und zusammen mit Alkohol."],"darreichung":["Tabletten","Retardkapseln","Injektionslösung","Infusionskonzentrat"]},"fusidinsaeure":{"wirkmechanismus":"Hemmt das Wachstum von Bakterien, indem es ihre Eiweissherstellung blockiert. Fusidinsäure hat eine steroidähnliche Struktur, wirkt aber nicht wie Kortison: Sie hält den Elongationsfaktor G (EF-G) am bakteriellen Ribosom fest und verhindert so, dass die Eiweisskette verlängert wird. Sie wirkt vor allem gegen Staphylokokken, auch gegen viele Methicillin-resistente Stämme, und dringt gut in Haut und Gewebe ein. Weil sich rasch Resistenzen bilden, soll die Behandlung kurz sein.","nebenwirkungen":{"haeufig":["Magen-Darm-Beschwerden wie Übelkeit, Erbrechen, Durchfall, Bauchschmerzen, Verdauungsbeschwerden (Tabletten)","Brennen, Juckreiz oder Schmerzen am Auge, kurzzeitig verschwommenes Sehen (Augentropfen)"],"gelegentlich":["Brennen, Reizung oder Schmerzen an der Auftragsstelle (Creme, Salbe)","Kontaktekzem, Ausschlag, Juckreiz, Rötung","Kopfschmerzen, Schwindel, Müdigkeit (Tabletten)","Lidschwellung, vermehrter Tränenfluss (Augentropfen)"],"selten":["Angioödem (Schwellung von Haut und Schleimhäuten), Nesselsucht, Blasenbildung","Bindehautentzündung (Creme oder Salbe im Augenbereich)"],"unbekannt":["Gelbsucht und Leberfunktionsstörungen (Tabletten)","Blutbildveränderungen bis Agranulozytose oder Panzytopenie (Tabletten, vor allem bei längerer Einnahme)","Rhabdomyolyse (Muskelzerfall), vor allem zusammen mit Statinen","Schwere allergische Reaktionen (Anaphylaxie)"]},"schwangerschaft":"Creme, Salbe und Augentropfen können angewendet werden, da kaum Wirkstoff in den Körper gelangt. Tabletten nur nach strenger ärztlicher Abwägung, besonders gegen Ende der Schwangerschaft (theoretisches Gelbsucht-Risiko beim Neugeborenen).","stillzeit":"Äusserliche Anwendung und Augentropfen möglich, aber nicht auf die Brust auftragen. Tabletten: Fusidinsäure geht in die Muttermilch über – nur nach ärztlicher Abwägung.","hinweise":["Wer ein Statin (Cholesterinsenker) einnimmt, muss dies vor einer Behandlung mit Fusidinsäure-Tabletten unbedingt angeben.","Creme und Salbe nach dem Auftragen von den Händen waschen und nicht länger als ärztlich verordnet anwenden.","Augentropfen: während einer Bindehautentzündung keine Kontaktlinsen tragen; nach dem Eintropfen erst Auto fahren, wenn die Sicht klar ist.","Fucicort enthält zusätzlich das stark wirksame Kortison Betamethason: nicht ohne ärztliche Anweisung im Gesicht oder grossflächig anwenden."],"darreichung":["Creme","Salbe","Augentropfen (zähflüssig)","Filmtabletten"]},"futibatinib":{"wirkmechanismus":"Bremst das Wachstum von Gallengangstumoren, die durch eine FGFR2-Genveränderung angetrieben werden. Futibatinib bindet kovalent und damit irreversibel an die Fibroblasten-Wachstumsfaktor-Rezeptoren FGFR1 bis FGFR4 und blockiert deren Signalübertragung. Weil FGFR auch den Phosphathaushalt regelt, steigt der Phosphatspiegel im Blut häufig an.","nebenwirkungen":{"sehrHaeufig":["Hyperphosphatämie (erhöhtes Phosphat im Blut)","Nagelveränderungen (Ablösung, Verfärbung, Entzündung)","Haarausfall, trockene Haut, Hand-Fuss-Syndrom","Stomatitis, Mundtrockenheit, Geschmacksstörungen","Durchfall, Verstopfung, Übelkeit, Erbrechen, Bauchschmerzen","Müdigkeit, Appetit- und Gewichtsabnahme","Gelenk- und Muskelschmerzen","Trockene Augen; erhöhte Leberwerte"],"haeufig":["Seröse Netzhautablösung (Ablösung des retinalen Pigmentepithels)","Verschwommenes Sehen","Harnwegsinfekte","Dehydratation (Flüssigkeitsmangel), Hyponatriämie","Nasenbluten, Hautausschlag"],"unbekannt":["Weichteil- und Gefässverkalkungen bei anhaltend hohem Phosphat"]},"schwangerschaft":"Nicht anwenden (im Tierversuch fruchtschädigend). Frauen und Männer mit Partnerin im gebärfähigen Alter müssen während und bis 1 Woche nach der Behandlung zuverlässig verhüten.","stillzeit":"Während der Behandlung und bis 1 Woche nach der letzten Dosis nicht stillen.","hinweise":["Einmal täglich zur gleichen Zeit einnehmen, mit oder ohne Essen; Tabletten ganz schlucken.","Phosphatarm essen (wenig Schmelzkäse, Wurst, Cola, Fertigprodukte) und Phosphatbinder wie verordnet einnehmen.","Sehstörungen sofort melden; augenärztliche Kontrollen vor Beginn und regelmässig während der Behandlung.","Regelmässige Blutkontrollen: Phosphat, Calcium und Leberwerte."],"darreichung":["Filmtabletten"]}});
